window.HS_LOAD(7,{"intro":[[["نبی کریمؐ اور صحابہ کرامؓ کس طرح سفر اور حضر میں لوگوں کو وعظ اور نصیحت کیا کرتے تھے اور دوسروں کی نصیحت قبول کیا کرتے تھے اور کس طرح دنیا کی ظاہری چیزوں اور اس کی لذتوں سے نگاہ ہٹا کر آخرت کی نعمتوں اور لذتوں کی طرف پھیر لیتے تھے اور ",""],["ٱللَّٰه","a"],[" تعالیٰ سے اس طرح ڈراتے تھے کہ آنکھوں سے آنسو جاری ہو جاتے اور دل ڈرنے لگ جاتے، گویا کہ آخرت ان کے سامنے ایک نمایاں اور کھلی ہوئی حقیقت تھی اور محشر کے حالات ان کی آنکھوں کے سامنے ہر وقت رہتے تھے، اور وہ کس طرح اپنے وعظ و نصیحت کے ذریعے امت محمدیہؐ کے ہاتھوں کو پکڑ کر انہیں آسمانوں اور زمین کے پیدا کرنے والے کی طرف متوجہ کرتے اور اس طرح اپنے وعظ و نصیحت کے ذریعہ شرک جلی اور خفی کی تمام باریک رگوں کو کاٹ دیتے۔",""]]],"topics":{"199":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوذرؓ","b"],[" فرماتے ہیں میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! حضرت ابراہیمؑ کے صحیفے کیا تھے؟ آپؐ نے فرمایا ان صحیفوں میں صرف مثالیں اور نصیحتیں تھیں (مثلاً ان میں یہ مضمون بھی تھا) اے مسلط ہونے والے بادشاہ! جسے آزمائش میں ڈالا جا چکا ہے اور جو دھوکہ میں پڑا ہوا ہے، میں نے تجھے اس لیے نہیں بھیجا تھا کہ تو جمع کر کے دنیا کے ڈھیر لگا لے، میں نے تو تجھے اس لیے بھیجا تھا کہ کسی مظلوم کی بد دعا کو میرے پاس آنے نہ دے کیونکہ جب کسی مظلوم کی بد دعا میرے پاس پہنچ جاتی ہے تو پھر میں اسے رد نہیں کرتا چاہے وہ مظلوم کافر ہی کیوں نہ ہو۔ اور جب تک عقل مند آدمی کی عقل مغلوب نہ ہو جائے اس وقت تک اسے چاہیے کہ وہ اپنے اوقات کی تقسیم کرے۔ کچھ وقت اپنے رب سے راز و نیاز کی باتیں کرنے کے لیے ہونا چاہیے، کچھ وقت اپنے نفس کے محاسبہ کے لیے ہونا چاہیے، کچھ وقت ",""],["ٱللَّٰه","a"],[" تعالیٰ کی کاریگری اور اس کی مخلوقات میں غور و فکر کرنے کے لیے ہونا چاہیے اور کچھ وقت کھانے پینے کی ضروریات کے لیے فارغ ہونا چاہیے۔ اور عقل مند کو چاہیے کہ صرف تین کاموں کے لیے سفر کرے: یا تو آخرت کا توشہ بنانے کے لیے یا اپنی معاش ٹھیک کرنے کے لیے یا کسی حلال لذت اور راحت کو حاصل کرنے کے لیے۔ اور عقل مند کو چاہیے کہ وہ اپنے زمانہ (کے حالات) پر نگاہ رکھے اور اپنی حالت کی طرف متوجہ رہے اور اپنی زبان کی حفاظت کرے، اور جو بھی اپنی گفتگو کا اپنے عمل سے محاسبہ کرے گا وہ کوئی بیکار بات نہیں کرے گا بلکہ صرف مقصد کی بات کرے گا۔ میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! حضرت موسیٰ علیہ السلام کے صحیفے کیا تھے؟ آپؐ نے فرمایا ان میں سب عبرت کی باتیں تھیں (مثلاً ان میں یہ مضمون بھی تھا کہ) مجھے اس آدمی پر تعجب ہے جسے موت کا یقین ہے اور وہ پھر خوش ہوتا ہے۔ مجھے اس آدمی پر تعجب ہے جسے جہنم کا یقین ہے اور وہ پھر ہنستا ہے۔ مجھے اس آدمی پر تعجب ہے جسے تقدیر کا یقین ہے اور وہ پھر اپنے آپ کو بلا ضرورت تھکاتا ہے۔ مجھے اس آدمی پر تعجب ہے جس نے دنیا کو دیکھا اور یہ بھی دیکھا کہ دنیا آنی جانی چیز ہے، ایک جگہ رہتی نہیں اور پھر مطمئن ہو کر اس سے دل لگاتا ہے۔ مجھے اس آدمی پر تعجب ہے جسے کل قیامت کے حساب کتاب کا یقین ہے اور پھر عمل نہیں کرتا۔ میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! آپ مجھے کچھ وصیت فرمائیں۔ آپؐ نے فرمایا میں تمہیں ",""],["ٱللَّٰه","a"],[" سے ڈرنے کی وصیت کرتا ہوں کیونکہ یہ تمام کاموں کی جڑ ہے۔ میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! کچھ اور فرمائیں۔ آپؐ نے فرمایا تلاوت قرآن اور ",""],["ٱللَّٰه","a"],[" کے ذکر کی پابندی کرو کیونکہ یہ زمین پر تمہارے لیے نور ہے اور آسمان میں تمہارے لیے ذخیرہ ہے۔ میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! کچھ اور فرمائیں۔ آپؐ نے فرمایا زیادہ ہنسنے سے بچو کیونکہ اس سے دل مردہ ہو جاتا ہے اور چہرے کا نور جاتا رہتا ہے۔ میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! کچھ اور فرمائیں۔ آپؐ نے فرمایا جہاد کو لازم پکڑو کیونکہ یہی میری امت کی رہبانیت ہے۔ میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! کچھ اور فرمائیں۔ آپؐ نے فرمایا زیادہ دیر خاموش رہا کرو کیونکہ اس سے شیطان دفع ہو جاتا ہے اور اس سے تمہیں دین کے کاموں میں مدد ملے گی۔ میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! مجھے کچھ اور فرمائیں۔ آپؐ نے فرمایا مسکینوں سے محبت رکھو اور ان کے ساتھ اٹھنا بیٹھنا رکھو۔ میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! کچھ اور فرمائیں۔ آپؐ نے فرمایا (دنیاوی مال و دولت اور ساز و سامان میں) ہمیشہ اپنے سے نیچے والے کو دیکھا کرو، اوپر والے کو مت دیکھا کرو کیونکہ اس طرح کرنے سے تم ",""],["ٱللَّٰه","a"],[" کی دی ہوئی نعمتوں کو حقیر نہیں سمجھو گے۔ میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! کچھ اور فرمائیں۔ آپؐ نے فرمایا حق بات کہو چاہے وہ کڑوی کیوں نہ ہو۔ میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! کچھ اور فرمائیں۔ آپؐ نے فرمایا جب تمہیں اپنے عیب معلوم ہیں تو دوسروں کے (عیب دیکھنے) سے رک جاؤ اور جو برے کام تم خود کرتے ہو ان کی وجہ سے دوسروں پر ناراض مت ہو۔ تمہیں عیب لگانے کے لیے یہ بات کافی ہے کہ تم اپنے عیبوں کو تو جانتے نہیں اور دوسروں میں عیب تلاش کر رہے ہو اور جن حرکتوں کو خود کرتے ہو ان کی وجہ سے دوسروں پر ناراض ہوتے ہو۔ پھر حضورؐ نے میرے سینے پر ہاتھ مار کر فرمایا اے ابوذر! حسن تدبیر کے برابر کوئی عقلمندی نہیں اور ناجائز، مشتبہ اور نامناسب کاموں سے رکنے کے برابر کوئی تقویٰ نہیں اور حسن اخلاق جیسی کوئی خاندانی شرافت نہیں۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Abi Dunya, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.473). Abu Nu'aym has reported the complete narration in his Hilyah (Vol.1 Pg.166), as have Hasan bin Sufyaan and Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.8 Pg.201)."]]}]},"200":{"lead":[],"stories":[{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں ایک دن حضورؐ نے اپنے صحابہؓ سے پوچھا تمہاری اور تمہارے اہل و عیال، مال اور عمل کی کیا مثال ہے؟ صحابہؓ نے عرض کیا ",""],["ٱللَّٰه","a"],[" اور اس کے رسول زیادہ جانتے ہیں۔ آپؐ نے فرمایا تمہاری اور تمہارے اہل و عیال، مال اور عمل کی مثال اس آدمی جیسی ہے جس کے تین بھائی ہوں۔ جب اس کی موت کا وقت قریب آیا تو اس نے بھائیوں کو بلا کر ایک بھائی سے کہا تم دیکھ رہے ہو کہ موت کی مصیبت میرے سر پر آ گئی ہے، اب تم میرے کیا کام آ سکتے ہو؟ اس نے کہا میں یہ کام کر سکتا ہوں کہ میں تمہاری تیمارداری کروں گا اور تمہاری خدمت سے اکتاؤں گا نہیں اور تمہارا ہر کام کروں گا، جب تم مر جاؤ گے تمہیں غسل دوں گا اور تمہیں کفن پہناؤں گا اور دوسروں کے ساتھ تمہارے جنازے کو اٹھاؤں گا اور تمہیں اٹھاؤں گا اور راستے کی تکلیف دہ چیز تم سے ہٹاؤں گا اور جب دفنا کر واپس آؤں گا تو پوچھنے والوں کے سامنے تمہاری خوبیاں بیان کر کے تمہاری تعریف کروں گا۔ اس کا یہ بھائی تو اس کے اہل و عیال اور رشتہ دار ہیں۔ اس بھائی کے بارے میں تم لوگوں کا کیا خیال ہے؟ صحابہؓ نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! اس کے کوئی خاص فائدے کی بات تو ہم نے سنی نہیں۔ آپؐ نے فرمایا پھر اس نے اپنے دوسرے بھائی سے کہا کیا تم دیکھ رہے ہو کہ موت کی مصیبت میرے سر پر آ گئی ہے، تو اب تم میرے کیا کام آ سکتے ہو؟ اس نے کہا جب تک آپ زندہ ہیں میں تو اسی وقت تک آپ کے کام آ سکوں گا، جب آپ مر جائیں گے تو آپ کا راستہ الگ اور میرا راستہ الگ۔ یہ بھائی اس کا مال ہے۔ یہ تمہیں کیسا لگا؟ صحابہؓ نے کہا یا رسول ",""],["ٱللَّٰه","a"],["! اس کے فائدے کی کوئی بات ہمارے سننے میں تو نہیں آئی۔ آپؐ نے فرمایا پھر اس نے تیسرے بھائی سے کہا تم دیکھ ہی رہے ہو موت میرے سر پر آ گئی ہے اور تم نے میرے اہل و عیال اور مال کا جواب بھی سن لیا ہے، تو اب تم میرے کیا کام آ سکتے ہو؟ اس نے کہا میں قبر میں تمہارا ساتھی ہوں گا اور وحشت میں تمہارا جی بہلاؤں گا اور اعمال تلنے کے دن ترازو میں بیٹھ کر اسے بھاری کراؤں گا۔ یہ بھائی اس کا عمل ہے۔ اس کے بارے میں تم لوگوں کا کیا خیال ہے؟ صحابہؓ نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! یہ بہترین بھائی اور بہترین ساتھی ہے۔ حضورؐ نے فرمایا بات بھی اسی طرح ہے۔ حضرت عائشہؓ فرماتی ہیں حضرت عبد",""],["ٱللَّٰه","a"],[" بن کرزؓ نے کھڑے ہو کر عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! کیا آپ مجھے اس بات کی اجازت دیتے ہیں کہ میں اس مثال کے بارے میں کچھ اشعار کہوں؟ آپؐ نے فرمایا ہاں اجازت ہے۔ حضرت عبد",""],["ٱللَّٰه","a"],["ؓ چلے گئے اور ایک ہی رات کے بعد اشعار تیار کر کے حضورؐ کی خدمت میں حاضر ہو گئے۔ انہیں دیکھ کر لوگ بھی جمع ہو گئے، انہوں نے حضورؐ کے سامنے کھڑے ہو کر یہ اشعار پڑھے",""]]],["q",[["فإني وأهلي والذي قدمت يدي كداع الله صحبه ثم قائل","a"]]],["q",[["لإخوته إذ هم ثلاثة إخوة أعينوا على أمر بي اليوم نازل","a"]]],["p",[["ترجمہ: \"میں اور میرے اہل و عیال اور میرے وہ عمل جو میرے ہاتھوں نے آگے بھیج دیے ہیں، ان سب کی مثال ایسی ہے کہ جیسے ایک آدمی کے تین بھائی تھے، اس نے ساتھیوں اور بھائیوں کو بلا کر ان سے کہا آج مجھ پر موت کی مصیبت آنے والی ہے، اس بارے میں میری مدد کرو۔\"",""]]],["q",[["فراق طويل غير منتق به فماذا لديكم في الذي هو غائل","a"]]],["p",[["ترجمہ: \"بہت لمبی جدائی ہے جس کا کوئی بھروسہ نہیں، اب بتاؤ اس ہلاک کرنے والی موت کے بارے میں تم لوگ میری کیا مدد کر سکتے ہو؟\"",""]]],["q",[["فقال امرؤ منهم أنا الصاحب الذي أطيعك فيها ما شئت قل التزايل","a"]]],["p",[["ترجمہ: \"ان تینوں میں سے ایک بولا کہ میں تمہارا ایسا ساتھی ہوں لیکن جدا ہونے سے پہلے تم جو کہو گے تمہاری وہ بات مانوں گا۔\"",""]]],["q",[["فأما إذا جد الفراق فإنني لما بيننا من خلة غير واصل","a"]]],["p",[["ترجمہ: \"اور جب جدائی ہو جائے گی تو پھر میں آپس کی دوستی کو باقی نہیں رکھ سکتا، اسے نہیں نباہ سکتا۔\"",""]]],["q",[["فخذ ما أردت الآن مني فإنني سيسلك بي في مهيل من مهائل","a"]]],["p",[["ترجمہ: \"اب تو تم مجھ سے جو چاہے لے لو لیکن جدائی کے بعد مجھے کسی ہولناک راستہ پر چلا دیا جائے گا، پھر کچھ نہیں لے سکو گے۔\"",""]]],["q",[["فإن تبقني لا أبق فاستنفدني وعجل صلاحا قبل حتف معاجل","a"]]],["p",[["ترجمہ: \"پھر اگر تم مجھے باقی رکھنا چاہو گے تو باقی نہیں رکھ سکو گے، لہٰذا مجھے خرچ کر کے ختم کر دو اور جلد آنے والی موت سے پہلے جلدی اپنے عمل ٹھیک کر لو۔\"",""]]],["q",[["وقال امرؤ قد كنت جدا أحبه وأوثره من بينهم في التفاضل","a"]]],["p",[["ترجمہ: \"پھر وہ آدمی بولا جس سے مجھے بہت محبت تھی اور زیادہ دینے اور بڑھانے میں میں اسے باقی تمام لوگوں پر ترجیح دیتا تھا۔\"",""]]],["q",[["غنائي أني جاهد لك ناصح إذا جد جد الكرب غير مقاتل","a"]]],["p",[["ترجمہ: \"اس نے کہا میں آپ کا اتنا کام کر سکتا ہوں کہ جب پریشان کن موت واقعی آ جائے گی تو آپ کو بچانے کی کوشش کروں گا اور آپ کا بھلا چاہوں گا لیکن میں آپ کی طرف سے موت سے نہیں لڑ سکوں گا۔\"",""]]],["q",[["ولكنني باك عليك ومعول ومثن بخير عند من هو سائل","a"]]],["p",[["ترجمہ: \"البتہ آپ کے مرنے پر روؤں گا اور خوب اونچی آواز سے روؤں گا اور آپ کے بارے میں جو بھی پوچھے گا میں اس کے سامنے آپ کی خوبیاں بیان کر کے آپ کی تعریف کروں گا۔\"",""]]],["q",[["ومتبع الماشين أمشي مشيعا أعين برفق عقبة كل حامل","a"]]],["p",[["ترجمہ: \"اور آپ کے جنازے کو لے کر جو لوگ چلیں گے ان کے پیچھے ان کو رخصت کرنے کے لیے بھی چلوں گا اور ہر اٹھانے والے کی باری میں نرمی سے اٹھا کر اس کی مدد کروں گا۔\"",""]]],["q",[["إلى بيت مثواك الذي أنت مدخل أرجع مقرونا بما هو شاغل","a"]]],["p",[["ترجمہ: \"میں جنازے کے ساتھ اس گھر تک جاؤں گا جہاں آپ کا ٹھکانہ ہے جس میں لوگ آپ کو داخل کر دیں گے، پھر واپس آ کر میں ان کاموں میں لگ جاؤں گا جن میں میں مشغول تھا۔\"",""]]],["q",[["كأن لم يكن بيني وبينك خلة ولا حسن ودمة في التباذل","a"]]],["p",[["ترجمہ: \"اور چند ہی دنوں کے بعد ایسی حالت ہو جائے گی کہ گویا میرے اور آپ کے درمیان کوئی دوستی ہی نہیں تھی اور نہ ہی کوئی عمدہ محبت تھی جس کی وجہ سے ہم ایک دوسرے پر خرچ کرتے تھے۔\"",""]]],["q",[["فذلك أهل المرء ذاك غناؤهم وليس وإن كانوا حراصا بطائل","a"]]],["p",[["ترجمہ: \"یہ مرنے والے کے اہل و عیال اور رشتہ دار ہیں، یہ بس اتنا ہی کام آ سکتے ہیں اگرچہ انہیں مرنے والے کو فائدہ پہنچانے کا بہت تقاضا ہے لیکن یہ اس سے زیادہ فائدہ نہیں پہنچا سکتے۔\"",""]]],["q",[["وقال امرؤ منهم أنا الأخ لا ترى أخا لك مثلي عند كرب النوازل","a"]]],["p",[["ترجمہ: \"ان میں سے تیسرے بھائی نے کہا میں آپ کا اصلی بھائی ہوں اور ہلا دینے والی پریشانی موت کے آنے پر آپ کو میرے جیسا کوئی بھائی نظر نہیں آئے گا۔\"",""]]],["q",[["لدى القبر تلقاني هنالك قاعدا أجادل عنك القول رجع التجادل","a"]]],["p",[["ترجمہ: \"آپ مجھے قبر کے پاس ملیں گے، میں وہاں بیٹھا ہوا ہوں گا اور باتوں میں آپ کی طرف سے جھگڑا کروں گا اور ہر سوال کا جواب دوں گا۔\"",""]]],["q",[["وأقعد يوم الوزن في الكفة التي تكون عليها جاهدا في التثاقل","a"]]],["p",[["ترجمہ: \"اور اعمال تولے جانے کے دن یعنی قیامت کے دن میں اس پلڑے میں بیٹھوں گا جس کو بھاری کرنے کی آپ پوری کوشش کر رہے ہوں گے۔\"",""]]],["q",[["فلا تنسني واعلم مكاني فإنني عليك شفيق ناصح غير خاذل","a"]]],["p",[["ترجمہ: \"لہٰذا آپ مجھے بھلا نہ دینا اور میرے مرتبہ کو جان لو کیونکہ میں آپ کا بڑا شفیق اور بہت خیر خواہ ہوں اور کبھی آپ کو بے یار و مددگار نہیں چھوڑوں گا۔\"",""]]],["q",[["فذلك ما قدمت من كل صالح تلاقيه إن أحسنت يوم التواصل","a"]]],["p",[["ترجمہ: \"یہ آپ کے وہ نیک اعمال ہیں جو آپ نے آگے بھیجے ہیں، اگر آپ ان کو اچھی طرح کریں گے تو ایک دوسرے سے ملاقات کے دن یعنی قیامت کے دن آپ کی ان اعمال سے ملاقات ہو جائے گی۔\" یہ اشعار سن کر حضورؐ بھی رونے لگے اور سارے مسلمان بھی۔ اس کے بعد حضرت عبد",""],["ٱللَّٰه","a"],[" بن کرزؓ مسلمانوں کی جس جماعت کے پاس سے گزرتے وہ انہیں بلا کر ان سے ان اشعار کی فرمائش کرتے اور جب حضرت عبد",""],["ٱللَّٰه","a"],["ؓ انہیں یہ اشعار سناتے تو وہ سب رونے لگ جاتے۔",""],[" (1)","s"]]]],"f":[["(1)","Ramhurmuzi in his Amthaal, as quoted in Kanzul Ummaal (Vol.8 Pg.124). The narration has also been reported by Ja'far Firyaabi in Kitaabul Kuna, Ibn Abi Aasim in Wahdaan, Ibn Shaaheen, Ibn Mandah in Sahaabah and Ibn Abi Dunya in Kifaalah, as quoted in Isaabah (Vol.2 Pg.362)."]]}]},"201":{"lead":[],"stories":[{"b":[["n",[["ایک مرتبہ حضرت عمرؓ نے ایک آدمی کو یہ نصیحت فرمائی کہ لوگوں میں لگ کر اپنے سے غافل نہ ہو جاؤ کیونکہ تم سے اپنے بارے میں پوچھا جائے گا، لوگوں کے بارے میں نہیں پوچھا جائے گا۔ ادھر ادھر پھر کر دن نہ گزار دیا کرو کیونکہ تم جو بھی عمل کرو گے وہ محفوظ کر لیا جائے گا۔ جب تم سے کوئی برا کام ہو جایا کرے تو اس کے بعد فوراً کوئی نیکی کا کام کر لیا کرو کیونکہ جس طرح نئی نیکی پرانے گناہ کو بہت زیادہ تلاش کرتی ہے اور اسے جلدی سے پا لیتی ہے، اسی طرح اس سے زیادہ تلاش کرنے والی میں نے کوئی چیز نہیں دیکھی۔ حضرت عمرؓ نے فرمایا جو چیز تمہیں تکلیف دیتی ہے اس سے تم کنارہ کشی اختیار کر لو اور نیک آدمی کو دوست بناؤ لیکن ایسا آدمی مشکل سے ملے گا اور اپنے معاملات میں ان لوگوں سے مشورہ لو جو ",""],["ٱللَّٰه","a"],[" سے ڈرتے ہیں۔",""],[" (1)","s"],[" (2)","s"]]]],"f":[["(1)","Dinawari, as quoted in Kanzul Ummaal (Vol.8 Pg.208)."],["(2)","Bayhaqi, as quoted in Kanzul Ummaal (Vol.8 Pg.208)."]]},{"b":[["n",[["حضرت سعید بن مسیبؒ","b"],[" کہتے ہیں حضرت عمر بن خطابؓ نے لوگوں کے لیے اٹھارہ باتیں مقرر کیں جو سب حکمت و دانائی کی باتیں تھیں۔ انہوں نے فرمایا (۱) جو تمہارے بارے میں ",""],["ٱللَّٰه","a"],[" کی نافرمانی کرے تم اسے اس جیسی اور کوئی سزا نہیں دے سکتے کہ تم اس کے بارے میں ",""],["ٱللَّٰه","a"],[" کی اطاعت کرو (۲) اور اپنے بھائی کی بات کو کسی اچھے رخ کی طرف لے جانے کی پوری کوشش کرو۔ ہاں اگر وہ بات ہی ایسی ہو کہ اسے اچھے رخ کی طرف لے جانے کی تم کوئی صورت نہ بنا سکو تو اور بات ہے (۳) اور مسلمان کی زبان سے جو بول بھی نکلا ہے اور تم اس کا کوئی بھی خیر کا مطلب نکال سکتے ہو تو اس سے برے مطلب کا گمان مت کرو (۴) جو آدمی خود ایسے کام کرتا ہے جس سے دوسروں کو بدگمانی کا موقع ملے تو وہ اپنے سے بدگمانی کرنے والے کو ہرگز ملامت نہ کرے (۵) جو اپنے راز کو چھپائے گا اختیار اس کے ہاتھ میں رہے گا (۶) اور سچے بھائیوں کے ساتھ رہنے کو لازم پکڑو، ان کے سایۂ خیر میں زندگی گزارو کیونکہ وسعت اور اچھے حالات میں وہ لوگ تمہارے لیے زینت کا ذریعہ اور مصیبت میں حفاظت کا سامان ہوں گے (۷) اور ہمیشہ سچ بولو چاہے سچ بولنے سے جان ہی چلی جائے (۸) بے فائدہ اور بیکار کاموں میں نہ لگو (۹) جو بات ابھی پیش نہیں آئی اس کے بارے میں مت پوچھو کیونکہ جو پیش آ چکی ہے اس کے تقاضوں سے ہی کہاں فرصت مل سکتی ہے (۱۰) اپنی حاجت اس کے پاس نہ لے جاؤ جو یہ نہیں چاہتا کہ تم اس میں کامیاب ہو جاؤ (۱۱) جھوٹی قسم کو ہلکا نہ سمجھو ورنہ ",""],["ٱللَّٰه","a"],[" تمہیں ہلاک کر دیں گے (۱۲) بدکاروں کے ساتھ نہ رہو ورنہ تم ان سے بدکاری سیکھ لو گے (۱۳) اپنے دشمن سے الگ رہو (۱۴) اپنے دوست سے بھی چوکنے رہو لیکن اگر وہ امانتدار ہے تو پھر اس کی ضرورت نہیں اور امانتدار صرف وہی ہو سکتا ہے جو ",""],["ٱللَّٰه","a"],[" سے ڈرنے والا ہو (۱۵) اور قبرستان میں جا کر خشوع اختیار کرو (۱۶) اور جب ",""],["ٱللَّٰه","a"],[" کی فرمانبرداری کا کام کرو تو عاجزی اور تواضع اختیار کرو (۱۷) اور جب ",""],["ٱللَّٰه","a"],[" کی نافرمانی ہو جائے تو ",""],["ٱللَّٰه","a"],[" کی پناہ چاہو (۱۸) اور اپنے تمام امور میں ان لوگوں سے مشورہ کیا کرو جو ",""],["ٱللَّٰه","a"],[" سے ڈرتے ہیں کیونکہ ",""],["ٱللَّٰه","a"],[" تعالیٰ فرماتے ہیں",""]]],["q",[["إِنَّمَا يَخْشَى ٱللَّهَ مِنْ عِبَادِهِ ٱلْعُلَمَٰٓؤُا","a"]]],["p",[["ترجمہ: \"خدا سے اس کے وہی بندے ڈرتے ہیں جو (اس کی عظمت کا) علم رکھتے ہیں۔\" (سورۂ فاطر، آیت 28)۔",""],[" (3)","s"]]]],"f":[["(3)","Khateeb, Ibn Asaakir and Ibn Najjaar, as quoted in Kanzul Ummaal (Vol.8 Pg.235)."]]},{"b":[["n",[["حضرت محمد بن شہابؒ","b"],[" کہتے ہیں حضرت عمر بن خطابؓ نے فرمایا لایعنی کاموں میں نہ لگو اور اپنے دشمن سے کنارہ کشی اختیار کرو اور اپنے دوست سے اپنی حفاظت کرو لیکن اگر وہ امانتدار ہے تو پھر ضرورت نہیں کیونکہ امانتدار انسان کے برابر کوئی چیز نہیں ہو سکتی اور کسی بدکار کی صحبت میں نہ رہو ورنہ وہ تمہیں بھی بدکاری سکھا دے گا اور کسی بدکار کو اپنا راز نہ بتاؤ اور اپنے تمام کاموں میں ان لوگوں سے مشورہ لو جو ",""],["ٱللَّٰه","a"],[" سے ڈرتے ہیں۔",""],[" (4)","s"]]]],"f":[["(4)","Abu Nu'aym in his Hilyah (Vol.1 Pg.55)."]]},{"b":[["n",[["حضرت سمرہ بن جندبؒ","b"],[" کہتے ہیں حضرت عمرؓ نے فرمایا مرد بھی تین قسم کے ہوتے ہیں اور عورتیں بھی تین قسم کی ہوتی ہیں۔ ایک عورت تو وہ ہے جو پاکدامن، مسلمان، نرم طبیعت، محبت کرنے والی، زیادہ بچے دینے والی ہو اور زمانہ کے فیشن کے خلاف اپنے گھر والوں کی مدد کرتی ہو (سادہ رہتی ہو) اور گھر والوں کو چھوڑ کر زمانہ کے فیشن پر نہ چلتی ہو، لیکن تمہیں ایسی عورتیں بہت کم ملیں گی۔ دوسری وہ عورت ہے جو خاوند سے بہت زیادہ مطالبے کرتی ہو اور بچے جننے کے علاوہ اس کا اور کوئی کام نہ ہو۔ تیسری وہ عورت ہے جو خاوند کے گلے کا طوق ہو اور جوں کی طرح سے چمٹی ہوئی ہو (یعنی بداخلاق بھی ہو اور اس کا مہر بھی زیادہ ہو جس کی وجہ سے اس کا خاوند اسے چھوڑ نہ سکتا ہو)۔ ایسی عورت کو ",""],["ٱللَّٰه","a"],[" تعالیٰ جس کی گردن میں چاہتے ہیں ڈال دیتے ہیں اور جب چاہتے ہیں اس کی گردن سے اتار لیتے ہیں۔ اور مرد بھی تین قسم کے ہوتے ہیں۔ ایک پاکدامن، منکسر المزاج، نرم طبیعت، درست رائے والا، اچھے مشورے دینے والا۔ جب اسے کوئی کام پیش آتا ہے تو خود سوچ کر فیصلہ کرتا ہے اور ہر کام کو اس کی جگہ رکھتا ہے۔ دوسرا وہ مرد ہے جو سمجھدار نہیں، اس کی اپنی کوئی رائے نہیں ہے لیکن جب اسے کوئی کام پیش آتا ہے تو وہ سمجھدار درست رائے والے لوگوں سے جا کر مشورہ کرتا ہے اور ان کے مشورے پر عمل کرتا ہے۔ تیسرا وہ مرد جو حیران و پریشان ہوتا ہے، اسے صحیح اور غلط کا پتہ نہیں چلتا یوں ہی ہلاک ہو جاتا ہے کیونکہ اس کی اپنی سمجھ پوری نہیں اور سمجھدار اور صحیح مشورہ دینے والوں کی مانتا نہیں۔",""],[" (5)","s"]]]],"f":[["(5)","Ibn Abi Shaybah, Ibn Abi Dunya, Kharaa'iti, Bayhaqi and Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.8 Pg.235)."]]},{"b":[["n",[["حضرت احنف بن قیسؒ","b"],[" کہتے ہیں حضرت عمر بن خطابؓ نے مجھ سے فرمایا اے احنف! جو آدمی زیادہ ہنستا ہے اس کا رعب کم ہو جاتا ہے۔ جو مذاق زیادہ کرتا ہے لوگ اسے ہلکا اور بے حیثیت سمجھتے ہیں، جو باتیں زیادہ کرتا ہے اس کی لغزشیں زیادہ ہو جاتی ہیں، جس کی لغزشیں زیادہ ہو جاتی ہیں اس کی حیا کم ہو جاتی ہے اور جس کی حیا کم ہو جاتی ہے اس کی پرہیزگاری کم ہو جاتی ہے اور جس کی پرہیزگاری کم ہو جاتی ہے اس کا دل مردہ ہو جاتا ہے۔",""],[" (6)","s"]]]],"f":[["(6)","Tabraani in his Awsat. Haythami (Vol.10 Pg.302) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت عمرؓ نے فرمایا جو زیادہ ہنستا ہے اس کا رعب کم ہو جاتا ہے اور جو مذاق زیادہ کرتا ہے لوگوں کی نگاہ میں وہ بے حیثیت ہو جاتا ہے اور جو کسی کام کو زیادہ کرتا ہے وہ اسی کام کے ساتھ مشہور ہو جاتا ہے۔ اس کے بعد پچھلی حدیث جیسا مضمون ذکر کیا ہے۔",""],[" (7)","s"]]]],"f":[["(7)","Ibn Abi Dunya, Askari, Bayhaqi and others, as quoted in Kanzul Ummaal (Vol.8 Pg.235)."]]},{"b":[["n",[["حضرت عمرؓ فرماتے ہیں ",""],["ٱللَّٰه","a"],[" کے کچھ بندے ایسے ہیں جو باطل کو کلیتہً چھوڑ کر اسے مٹا دیتے ہیں اور حق کا بار بار تذکرہ کر کے اسے زندہ کرتے ہیں۔ جب انہیں کسی عمل کی ترغیب دی جاتی ہے تو وہ اس کا اثر لیتے ہیں اور ڈر جاتے ہیں اور ڈر کی وجہ سے کبھی بے خوف نہیں ہوتے۔ جن چیزوں کو انہوں نے آنکھ سے نہیں دیکھا انہیں یقین کی طاقت سے دیکھ لیتے ہیں اور یقین کو ان غیبی امور کے ساتھ ملاتے ہیں جن سے کبھی جدا نہیں ہوتے۔ خوف خداوندی نے انہیں عیوب سے بالکل پاک صاف کر دیا۔ ہمیشہ باقی رہنے والی نعمتوں کی وجہ سے دنیا کی فانی لذتوں کو چھوڑ دیتے ہیں۔ دنیا کی زندگی ان کے لیے نعمت ہے اور موت ان کے لیے باعث عزت ہے۔ اور بڑی بڑی آنکھوں والی حوروں سے ان کی شادی کر دی جائے گی اور ہمیشہ نوعمر رہنے والے لڑکے ان کی خدمت کریں گے۔",""],[" (8)","s"]]]],"f":[["(8)","Abu Nu'aym in his Hilyah (Vol.1 Pg.55)."]]},{"b":[["n",[["حضرت عمرؓ فرماتے ہیں تم کتاب ",""],["ٱللَّٰه","a"],[" کے برتن اور علم کے چشمے بن جاؤ یعنی قرآن اپنے اندر اتار لو پھر علم اندر سے پھوٹ کر نکلے گا اور ",""],["ٱللَّٰه","a"],[" تعالیٰ سے ایک دن میں ایک دن کی روزی مانگو۔ اور ایک روایت میں یہ بھی ہے کہ کثرت سے توبہ کرنے والوں کے پاس بیٹھا کرو کیونکہ ان کے دل سب سے زیادہ نرم ہوتے ہیں۔",""],[" (9)","s"]]]],"f":[["(9)","Abu Nu'aym in his Hilyah (Vol.1 Pg.51)."]]},{"b":[["n",[["حضرت عمرؓ فرماتے ہیں جو ",""],["ٱللَّٰه","a"],[" سے ڈرے گا وہ کبھی کسی پر اپنا غصہ نہیں نکالے گا یعنی کسی سے انتقام نہیں لے گا بلکہ اپنا غصہ پی جائے گا اور جو ",""],["ٱللَّٰه","a"],[" سے ڈرے گا وہ اپنی مرضی کا ہر کام نہیں کر سکے گا اور اگر قیامت کا دن نہ ہوتا تو جو تمہیں نظر آ رہا ہے وہ نہ ہوتا بلکہ افراتفری کا کچھ اور عالم ہوتا۔",""],[" (10)","s"]]]],"f":[["(10)","Ibn Abi Dunya, Dinawari in Al Mujaalasah and Haakim in Al Kuna, as quoted in Kanzul Ummaal (Vol.8 Pg.235)."]]},{"b":[["n",[["حضرت عمرؓ فرماتے ہیں جو لوگوں کے ساتھ انصاف کرتا ہے اور اس کے لیے اپنی جان پر جو مشقت جھیلنی پڑے اسے جھیلتا ہے، اسے اپنے تمام کاموں میں کامیابی ملے گی اور ",""],["ٱللَّٰه","a"],[" تعالیٰ کی فرمانبرداری کی وجہ سے ذلت اٹھانا نافرمانی کی وجہ سے عزت پانے کی بنسبت نیکی کے زیادہ قریب ہے۔",""],[" (11)","s"]]]],"f":[["(11)","Kharaa'iti and others, as quoted in Kanzul Ummaal (Vol.8 Pg.235)."]]},{"b":[["n",[["حضرت امام مالکؒ","b"],[" کہتے ہیں مجھے یہ روایت پہنچی ہے کہ حضرت عمر بن خطابؓ نے فرمایا آدمی تقویٰ سے عزت پاتا ہے اور اسے دین سے شرافت ملتی ہے۔ آدمی کی مروت اور مردانگی عمدہ اخلاق ہیں۔ بہادری اور بزدلی خدا داد صفات ہیں۔ بہادر آدمی تو ان لوگوں کی طرف سے بھی لڑتا ہے جنہیں جانتا ہے اور ان کی طرف سے بھی لڑتا ہے جنہیں نہیں جانتا اور بزدل آدمی تو اپنے ماں باپ کو بھی چھوڑ کر بھاگ جاتا ہے۔ دنیا والوں کی نگاہ میں عزت مال سے ملتی ہے لیکن ",""],["ٱللَّٰه","a"],[" کے ہاں تقویٰ کی وجہ سے ملتی ہے۔ تم کسی فارسی، عجمی اور نبطی سے صرف تقویٰ کی وجہ سے بہتر ہو سکتے ہو، عربی ہونے کی وجہ سے نہیں ہو سکتے۔",""],[" (12)","s"]]]],"f":[["(12)","Ibn Abi Shaybah, Askari, Ibn Jareer, Daaraqutni and Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.8 Pg.235)."]]},{"b":[["n",[["حضرت سفیان ثوریؒ","b"],[" کہتے ہیں حضرت عمر بن خطابؓ نے حضرت ابوموسیٰ اشعریؓ کو خط میں یہ لکھا کہ حکمت و دانائی عمر بڑی ہونے سے حاصل نہیں ہوتی بلکہ یہ تو ",""],["ٱللَّٰه","a"],[" کی دین ہے، جسے ",""],["ٱللَّٰه","a"],[" چاہتے ہیں دیتے ہیں اور کمینے کاموں اور گھٹیا اخلاق سے بچو۔",""],[" (13)","s"]]]],"f":[["(13)","Ibn Abi Dunya and Dinawari, as quoted in Kanzul Ummaal (Vol.8 Pg.235)."]]},{"b":[["n",[["حضرت عمرؓ نے اپنے صاحبزادے حضرت عبد",""],["ٱللَّٰه","a"],[" بن عمرؓ کو خط میں یہ لکھا اما بعد! میں تمہیں ",""],["ٱللَّٰه","a"],[" سے ڈرنے کی وصیت کرتا ہوں کیونکہ جو ",""],["ٱللَّٰه","a"],[" سے ڈرتا ہے ",""],["ٱللَّٰه","a"],[" اسے ہر شر اور فتنے سے بچاتے ہیں اور جو ",""],["ٱللَّٰه","a"],[" پر توکل کرتا ہے ",""],["ٱللَّٰه","a"],[" تعالیٰ اس کے تمام کاموں کی کفایت کرتے ہیں اور جو ",""],["ٱللَّٰه","a"],[" کو قرض دیتا ہے یعنی دوسروں پر اپنا مال ",""],["ٱللَّٰه","a"],[" کے لیے خرچ کرتا ہے ",""],["ٱللَّٰه","a"],[" تعالیٰ اسے بہترین بدلہ عطا فرماتے ہیں اور جو ",""],["ٱللَّٰه","a"],[" کا شکر ادا کرتا ہے ",""],["ٱللَّٰه","a"],[" تعالیٰ اس کی نعمت کو بڑھاتے ہیں اور تقویٰ ہر وقت تمہارا نصب العین، تمہارے اعمال کا سہارا اور ستون اور تمہارے دل کی صفائی کرنے والا ہونا چاہیے۔ جس کی کوئی نیت نہیں ہوتی اس کا کوئی عمل معتبر نہیں ہوگا۔ جس نے ثواب لینے کی نیت سے عمل نہ کیا اسے کوئی اجر نہیں ملے گا۔ جس میں نرمی نہیں ہوگی اسے اپنے مال سے بھی فائدہ نہیں ہوگا۔ جب تک پہلا کپڑا پرانا نہ ہو جائے نیا نہیں پہننا چاہیے۔",""],[" (14)","s"]]]],"f":[["(14)","Ibn Abi Dunya, Abu Bakr Sowli and Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.8 Pg.207)."]]},{"b":[["n",[["حضرت جعفر بن برقانؒ","b"],[" کہتے ہیں مجھے یہ روایت پہنچی ہے کہ حضرت عمر بن خطابؓ نے اپنے ایک گورنر کو خط لکھا، خط کے آخر میں یہ مضمون تھا فراخی اور وسعت والے حالات میں، سختی والے حالات کے حساب سے پہلے (جو قیامت کے دن ہوگا) اپنے نفس کا خود محاسبہ کرو کیونکہ جو فراخی اور نعمت والے حالات میں سختی کے حساب سے پہلے اپنے نفس کا محاسبہ کرے گا وہ انجام کار خوش ہوگا بلکہ اس کے حالات قابل رشک ہوں گے اور جس کو دنیا کی زندگی نے (",""],["ٱللَّٰه","a"],[" سے، آخرت سے اور دین سے) غافل رکھا اور وہ برائیوں میں مشغول رہا تو انجام کار وہ ندامت اٹھائے گا اور حسرت و افسوس کرتا رہے گا۔ جو نصیحت تمہیں کی جا رہی ہے اسے یاد رکھو تاکہ تمہیں جن کاموں سے روکا جا رہا ہے ان سے رک سکو۔",""],[" (15)","s"]]]],"f":[["(15)","Bayhaqi in his Zuhd and Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.8 Pg.207)."]]},{"b":[["n",[["حضرت عمرؓ نے حضرت معاویہ بن ابی سفیانؓ کو خط میں یہ مضمون لکھا اما بعد! حق کو ہر حال میں لازم پکڑو، اس طرح حق تمہارے لیے اہل حق کے مراتب کھول دے گا اور ہمیشہ حق کے مطابق فیصلہ کرو۔",""],[" (16)","s"]]]],"f":[["(16)","Abul Hasan Rizqawi in his Juz, as quoted in Kanzul Ummaal (Vol.8 Pg.208)."]]}]},"202":{"lead":[],"stories":[{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں جب حضرت عمرؓ نے حضرت علیؓ سے فرمایا اے ابوالحسن! مجھے کچھ نصیحت کرو۔ حضرت علیؓ نے کہا آپ اپنے یقین کو شک نہ بنائیں (یعنی روزی کا ملنا یقینی ہے، اس کی تلاش میں اس طرح اور اتنا نہ لگیں کہ گویا آپ کو اس میں کچھ شک ہے) اور اپنے علم کو جہالت نہ بنائیں (جو علم پر عمل نہیں کرتا وہ اور جاہل دونوں برابر ہوتے ہیں) اور اپنے گمان کو حق نہ سمجھیں (یعنی آپ اپنی رائے کو وحی کی طرح حق نہ سمجھیں) اور یہ بات آپ جان لیں کہ آپ کی دنیا تو صرف اتنی ہے کہ جو آپ کو ملی اور آپ نے اسے آگے چلا دیا یا تقسیم کر کے برابر کر دیا یا پہن کر پرانا کر دیا۔ حضرت عمرؓ نے فرمایا اے ابوالحسن! آپ نے سچ کہا۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.8 Pg.221)."]]},{"b":[["n",[["حضرت علی بن ابی طالبؓ نے حضرت عمرؓ سے کہا اے امیر المومنین! اگر آپ کی خوشی یہ ہے کہ آپ اپنے دونوں ساتھیوں یعنی حضورؐ اور حضرت ابوبکرؓ سے جا ملیں تو آپ اپنی امیدیں مختصر کر لیں اور کھانا کھائیں لیکن پیٹ نہ بھریں اور لنگی بھی چھوٹی پہنیں اور کرتے پر پیوند لگائیں اور اپنے ہاتھ سے جوتی گانٹھیں۔ اس طرح کریں گے تو ان دونوں سے جا ملیں گے۔",""],[" (2)","s"]]]],"f":[["(2)","Bayhaqi, as quoted in Kanzul Ummaal (Vol.8 Pg.219)."]]},{"b":[["n",[["حضرت علیؓ نے فرمایا خیر یہ نہیں ہے کہ تمہارا مال اور تمہاری اولاد زیادہ ہو جائے بلکہ خیر یہ ہے کہ تمہارا علم زیادہ ہو اور تمہاری بردباری کی صفت بڑی ہو اور اپنے رب کی عبادت میں تم لوگوں سے آگے نکلنے کی کوشش کرو۔ اگر تم سے نیکی کا کام ہو جائے تو ",""],["ٱللَّٰه","a"],[" کی تعریف کرو اور اگر برائی کا کام ہو جائے تو ",""],["ٱللَّٰه","a"],[" سے استغفار کرو اور دنیا میں صرف دو آدمیوں میں سے ایک کے لیے خیر ہے۔ ایک تو وہ آدمی جس سے کوئی گناہ ہو گیا اور پھر اس نے توبہ کر کے اس کی تلافی کر لی۔ دوسرا وہ آدمی جو نیک کاموں میں جلدی کرتا ہو۔ اور جو عمل تقویٰ کے ساتھ ہو وہ کم شمار نہیں ہو سکتا کیونکہ جو عمل ",""],["ٱللَّٰه","a"],[" کے ہاں قبول ہو وہ کیسے کم شمار ہو سکتا ہے (کیونکہ قرآن میں ہے کہ ",""],["ٱللَّٰه","a"],[" متقیوں کے عمل کو قبول فرماتے ہیں)۔",""],[" (3)","s"]]]],"f":[["(3)","Abu Nu'aym in his Hilyah (Vol.1 Pg.75). Ibn Asaakir has reported a similar narration, as quoted in Kanzul Ummaal (Vol.8 Pg.221)."]]},{"b":[["n",[["حضرت عقبہ بن ابی الصہباءؒ","b"],[" کہتے ہیں جب ابن ملجم نے حضرت علیؓ کو خنجر مارا تو حضرت حسنؓ ان کی خدمت میں حاضر ہوئے۔ حضرت حسنؓ رو رہے تھے۔ حضرت علیؓ نے فرمایا اے میرے بیٹے! کیوں رو رہے ہو؟ عرض کیا میں کیوں نہ روؤں جبکہ آج آپ کا آخرت کا پہلا دن اور دنیا کا آخری دن ہے۔ حضرت علیؓ نے فرمایا چار اور چار (کل آٹھ) چیزوں کو پلے باندھ لو۔ ان آٹھ چیزوں کو اگر تم اختیار کرو گے تو پھر تمہارا کوئی عمل تمہیں نقصان نہیں پہنچا سکے گا۔ حضرت حسنؓ نے عرض کیا اے ابا جان! وہ چیزیں کیا ہیں؟ فرمایا سب سے بڑی مالداری عقلمندی ہے یعنی مال سے بھی زیادہ کام آنے والی چیز عقل اور سمجھ ہے اور سب سے بڑی فقیری حماقت اور بے وقوفی ہے۔ سب سے زیادہ وحشت کی چیز اور سب سے بڑی تنہائی عجب اور خود پسندی ہے اور سب سے زیادہ بڑائی اچھے اخلاق ہیں۔ حضرت حسنؓ فرماتے ہیں میں نے کہا اے ابا جان! یہ چار چیزیں تو ہو گئیں، مجھے باقی چار چیزیں بھی بتا دیں۔ فرمایا بے وقوف کی دوستی سے بچنا کیونکہ وہ فائدہ پہنچاتے پہنچاتے تمہارا نقصان کر دے گا اور جھوٹے کی دوستی سے بچنا کیونکہ جو تم سے دور ہے یعنی تمہارا دشمن ہے اسے تمہارے قریب کر دے گا اور جو تمہارے قریب ہے یعنی تمہارا دوست ہے اسے تم سے دور کر دے گا (یا وہ دور والی چیز کو نزدیک اور نزدیک والی چیز کو دور بتائے گا اور تمہارا نقصان کر دے گا) اور کنجوس کی دوستی سے بھی بچنا کیونکہ جب تمہیں اس کی سخت ضرورت ہوگی وہ اس وقت تم سے دور ہو جائے گا اور بدکار کی دوستی سے بچنا کیونکہ وہ تمہیں معمولی سی چیز کے بدلے میں بیچ دے گا۔",""],[" (4)","s"]]]],"f":[["(4)","Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.8 Pg.236)."]]},{"b":[["n",[["حضرت علیؓ نے فرمایا توفیق خداوندی سب سے بہتر قائد ہے اور اچھے اخلاق بہترین ساتھی ہیں اور عقلمندی بہترین مصاحب ہے، حسن ادب بہترین میراث ہے اور عجب و خود پسندی سے زیادہ سخت تنہائی اور وحشت والی کوئی چیز نہیں۔",""],[" (5)","s"]]]],"f":[["(5)","Bayhaqi and Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.8 Pg.236)."]]},{"b":[["n",[["حضرت علیؓ نے فرمایا اس سے مت دیکھو کہ کوئی بات کر رہا ہے بلکہ یہ دیکھو کہ کیا بات کہہ رہا ہے۔ حضرت علیؓ نے فرمایا ہر بھائی چارہ ختم ہو جاتا ہے، صرف وہی بھائی چارہ باقی رہتا ہے جو لالچ کے بغیر ہو۔",""],[" (6)","s"]]]],"f":[["(6)","Sam'aani in his Dalaa'il, as quoted in Kanzul Ummaal (Vol.8 Pg.236)."]]}]},"203":{"lead":[],"stories":[{"b":[["n",[["حضرت نمران بن مخمرؒ","b"],[" فرماتے ہیں حضرت ابوعبیدہ بن جراحؓ لشکر میں چلے جا رہے تھے، فرمانے لگے بہت سے لوگ ایسے ہیں جو اپنے کپڑوں کو تو خوب اجلا اور سفید کر رہے ہیں لیکن اپنے دین کو میلا کر رہے ہیں یعنی دین کا نقصان کر کے دنیا اور ظاہری شان و شوکت حاصل کر رہے ہیں۔ غور سے سنو! بہت سے لوگ دیکھنے میں تو اپنے نفس کا اکرام کرنے والے ہوتے ہیں لیکن حقیقت میں وہ اپنے نفس کی بے عزتی کرنے والے ہوتے ہیں۔ پرانے گناہوں کو نئی نیکیوں کے ذریعے ختم کرو۔ اگر تم میں سے کوئی اتنے گناہ کر لے جس سے زمین و آسمان کے درمیان کا خلاء بھر جائے اور پھر وہ ایک نیکی کر لے تو یہ نیکی ان سب گناہوں پر غالب آ جائے گی۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Nu'aym in his Hilyah (Vol.1 Pg.102)."]]},{"b":[["n",[["حضرت سعید بن ابی سعید مقبریؒ","b"],[" فرماتے ہیں حضرت ابوعبیدہ بن جراحؓ کی قبر اردن میں ہے۔ جب وہ طاعون میں مبتلا ہوئے تو وہاں جتنے مسلمان تھے ان سب کو بلا کر فرمایا میں تمہیں وصیت کرنے لگا ہوں، اگر تم اسے قبول کرو گے تو ہمیشہ خیر پر رہو گے۔ نماز کو قائم کرو، زکوٰۃ ادا کرو، رمضان کے روزے رکھو، صدقہ خیرات دو، حج اور عمرہ کرتے رہو، ایک دوسرے کو وصیت کرو، اپنے امیروں کی خیر خواہی کرو، ان کو دھوکہ نہ دو اور دنیا تمہیں ",""],["ٱللَّٰه","a"],[" کی یاد سے غافل نہ کرنے پائے۔ اگر کسی آدمی کو ہزار برس کی زندگی بھی مل جائے تو آخرکار اسے اسی جگہ جانا ہوگا جہاں آج تم مجھے جاتا ہوا دیکھ رہے ہو۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے تمام بنی آدم پر موت کو لکھ دیا ہے، لہٰذا ان سب کو مرنا ہے اور ان میں سب سے زیادہ عقلمند وہ ہے جو اپنے رب کی سب سے زیادہ اطاعت کرنے والا اور اپنی آخرت کے لیے سب سے زیادہ عمل کرنے والا ہے۔ والسلام علیکم ورحمۃ ",""],["ٱللَّٰه","a"],[" وبرکاتہ۔ اے معاذ بن جبل! آپ لوگوں کو نماز پڑھائیں۔ پھر حضرت ابوعبیدہؓ کا انتقال ہو گیا۔ پھر حضرت معاذؓ نے لوگوں میں کھڑے ہو کر فرمایا اے لوگو! تم ",""],["ٱللَّٰه","a"],[" کے سامنے اپنے گناہوں سے سچی توبہ کرو کیونکہ جو بندہ بھی گناہوں سے توبہ کر کے ",""],["ٱللَّٰه","a"],[" کے سامنے حاضر ہوگا تو اس کا ",""],["ٱللَّٰه","a"],[" پر یہ حق ہوگا کہ ",""],["ٱللَّٰه","a"],[" اس کے سارے گناہ معاف کر دے لیکن اس توبہ سے قرض معاف نہیں ہوگا، وہ تو ادا ہی کرنا ہوگا کیونکہ بندہ اپنے قرضہ کے بدلے میں گروی رکھ دیا جائے گا۔ تم میں سے جس نے اپنے بھائی کو چھوڑا ہوا ہے اسے چاہیے کہ وہ خود جا کر اپنے بھائی سے ملاقات کرے اور اس سے مصافحہ کرے کیونکہ کسی مسلمان کو اپنا بھائی تین دن سے زیادہ نہیں چھوڑنا چاہیے، یہ بہت بڑا گناہ ہے۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Asaakir, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.74)."]]},{"b":[["n",[["حضرت ابوعبیدہؓ نے فرمایا مومن کے دل کی مثال چڑیا جیسی ہے جو ہر دن نامعلوم کتنی مرتبہ ادھر ادھر پلٹتا رہتا ہے (اس لیے آدمی مشورہ کے تابع ہو کر چلے)۔",""],[" (3)","s"]]]],"f":[["(3)","Abu Nu'aym in his Hilyah (Vol.1 Pg.102)."]]}]},"204":{"lead":[],"stories":[{"b":[["n",[["حضرت محمد بن سیرینؒ","b"],[" کہتے ہیں حضرت معاذ بن جبلؓ کے پاس ان کے ساتھی بیٹھے ہوئے تھے جو انہیں سلام کرنے اور رخصت کرنے آئے ہوئے تھے۔ اتنے میں حضرت معاذؓ کے پاس ایک آدمی آیا۔ حضرت معاذؓ نے اس سے فرمایا میں تمہیں دو باتوں کی وصیت کرتا ہوں، اگر تم نے ان دونوں کی پابندی کی تو تم ہر شر اور فتنہ سے محفوظ رہو گے۔ دنیا کا جو تمہارا حصہ ہے اس کی بھی تمہیں ضرورت ہے، اس کے بغیر گزارہ نہیں، لیکن تمہیں آخرت کے حصہ کی اس سے زیادہ ضرورت ہے، اس لیے دنیا کے حصے پر آخرت کے حصے کو ترجیح دو اور آخرت کا ایسا انتظام کرو کہ تم جہاں بھی جاؤ وہ تمہارے ساتھ جائے۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Nu'aym in his Hilyah (Vol.1 Pg.234)."]]},{"b":[["n",[["حضرت عمرو بن میمون اودیؒ","b"],[" کہتے ہیں حضرت معاذ بن جبلؓ نے ہم لوگوں میں کھڑے ہو کر فرمایا اے بنی اود! میں ",""],["ٱللَّٰه","a"],[" کے رسولؐ کا قاصد ہوں۔ اچھی طرح جان لو کہ سب کو لوٹ کر ",""],["ٱللَّٰه","a"],[" کے ہاں جانا ہے، پھر جنت میں جانا ہوگا یا جہنم میں اور وہاں جا کر ہمیشہ رہنا ہوگا، وہاں سے آگے کہیں جانا نہیں ہوگا اور ایسے جسموں میں ہم ہمیشہ رہیں گے جنہیں موت نہیں آئے گی۔",""],[" (2)","s"]]]],"f":[["(2)","Abu Nu'aym in his Hilyah (Vol.1 Pg.236)."]]},{"b":[["n",[["حضرت معاویہ بن قرہؒ","b"],[" کہتے ہیں حضرت معاذ بن جبلؓ نے اپنے بیٹے سے فرمایا جب تم نماز پڑھنے لگو تو دنیا سے جانے والے کی طرح نماز پڑھا کرو اور یوں سمجھا کرو کہ اب دوبارہ نماز پڑھنے کا موقع نہیں ملے گا۔ اور اے میرے بیٹے! یہ بات جان لو کہ مومن جب مرتا ہے تو اس کے پاس دو قسم کی نیکیاں ہوتی ہیں، ایک تو وہ نیکی جو اس نے آگے بھیج دی، دوسری وہ جسے وہ دنیا میں چھوڑ کر جا رہا ہے یعنی صدقہ جاریہ۔",""],[" (3)","s"]]]],"f":[["(3)","Abu Nu'aym in his Hilyah (Vol.1 Pg.234)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن سلمہؒ","b"],[" کہتے ہیں ایک آدمی نے حضرت معاذ بن جبلؓ کی خدمت میں عرض کیا مجھے کچھ سکھا دیں۔ فرمایا تم میری بات مانو گے؟ اس نے کہا مجھے آپ کی بات ماننے کا بہت شوق ہے۔ فرمایا کبھی روزہ رکھا کرو کبھی افطار کیا کرو اور رات کو کبھی نماز پڑھا کرو اور کبھی سویا کرو اور کمائی کیا کرو اور گناہ نہ کرو اور تم پوری کوشش کرو کہ تمہاری موت مسلمان ہونے کی حالت میں آئے اور مظلوم کی بددعا سے بچو۔",""],[" (4)","s"]]]],"f":[["(4)","Abu Nu'aym in his Hilyah (Vol.1 Pg.233)."]]},{"b":[["n",[["حضرت معاذ بن جبلؓ نے فرمایا تین کام ایسے ہیں کہ جو انہیں کرے گا وہ اپنے آپ کو بیزاری اور نفرت کے لیے پیش کرے گا یعنی لوگ اس سے بیزار ہو کر نفرت کریں گے: بغیر تعجب کی بات کے ہنسنا اور بغیر جاگے رات بھر سونا اور بغیر بھوک کے کھانا۔",""],[" (5)","s"]]]],"f":[["(5)","Abu Nu'aym in his Hilyah (Vol.1 Pg.237)."]]},{"b":[["n",[["حضرت معاذ بن جبلؓ نے فرمایا تنگدستی کی آزمائش سے تم لوگوں کا امتحان لیا گیا، اس میں تو تم کامیاب ہو گئے، تم نے صبر سے کام لیا۔ اب خوشحالی کی آزمائش میں ڈال کر تمہارا امتحان لیا جائے گا اور مجھے تم پر سب سے زیادہ ڈر عورتوں کی آزمائش کا ہے جب وہ سونے چاندی کے کنگن پہن لیں گی اور شام کی باریک اور یمن کی پھولدار چادریں پہن لیں گی تو وہ مالدار مرد کو تھکا دیں گی اور فقیر مرد کے ذمہ ایسی چیزیں لگا دیں گی جو اسے میسر نہیں ہوں گی۔",""],[" (6)","s"]]]],"f":[["(6)","Abu Nu'aym in his Hilyah (Vol.1 Pg.236)."]]}]},"205":{"lead":[],"stories":[{"b":[["n",[["حضرت ابن مسعودؓ نے فرمایا مجھے اس آدمی پر بہت غصہ آتا ہے جو مجھے فارغ نظر آتا ہے، نہ آخرت کے کسی عمل میں لگا ہوا ہے اور نہ دنیا کے کسی کام میں۔ حضرت ابن مسعودؓ نے فرمایا مجھے تم میں سے کوئی آدمی ایسا نہیں ملنا چاہیے جو رات کو مردہ پڑا رہے اور دن کو قطرب کیڑے کی طرح بھدکتا پھرے۔ یعنی رات بھر تو پڑا سوتا رہے اور دن بھر کے کاموں میں خوب بھاگ دوڑ کرے۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Nu'aym in his Hilyah (Vol.1 Pg.130). Abdur Razzaaq has reported a similar narration, as quoted in Kanzul Ummaal (Vol.8 Pg.232)."]]},{"b":[["n",[["حضرت عبد",""],["ٱللَّٰه","a"],[" بن مسعودؓ نے فرمایا دنیا کا صاف حصہ تو چلا گیا اور گدلا حصہ رہ گیا ہے، لہٰذا آج تو موت ہر مسلمان کے لیے تحفہ ہے۔ ایک روایت میں یہ ہے کہ دنیا تو پہاڑ کی چوٹی کے تالاب کی طرح ہے جس کا صاف حصہ جا چکا ہو اور گدلا حصہ رہ گیا ہو۔",""],[" (2)","s"]]]],"f":[["(2)","Abu Nu'aym in his Hilyah (Vol.1 Pg.131)."]]},{"b":[["n",[["حضرت عبد",""],["ٱللَّٰه","a"],["ؓ نے فرمایا غور سے سنو! وہ ناگوار اور ناپسندیدہ چیزیں کیا ہی اچھی ہیں، ایک موت اور دوسری فقیری۔ اور ",""],["ٱللَّٰه","a"],[" کی قسم! انسان کی دو ہی حالتیں ہوتی ہیں، یا مالداری یا فقیری۔ اور مجھے اس کی کوئی پرواہ نہیں ہے کہ ان دونوں میں سے کونسی حالت میں مجھے مبتلا کیا جائے۔ اگر مالداری کی حالت ہوگی تو میں اپنے مال کے ذریعہ سے لوگوں کے ساتھ غمخواری اور مہربانی کا معاملہ کروں گا (اور یوں ",""],["ٱللَّٰه","a"],[" کا حکم پورا کروں گا) اور اگر فقیری کی حالت ہوگی تو صبر کروں گا (اور یوں ",""],["ٱللَّٰه","a"],[" کا حکم پورا کروں گا)۔",""],[" (3)","s"]]]],"f":[["(3)","Abu Nu'aym in his Hilyah (Vol.1 Pg.132)."]]},{"b":[["n",[["حضرت عبد",""],["ٱللَّٰه","a"],["ؓ نے فرمایا کوئی بندہ اس وقت تک ایمان کی حقیقت تک نہیں پہنچ سکتا جب تک وہ ایمان کی چوٹی تک نہ پہنچ جائے اور اس وقت تک ایمان کی چوٹی تک نہیں پہنچ سکتا جب تک کہ اس کے نزدیک فقیری مالداری سے اور چھوٹا بننا بڑا بننے سے زیادہ محبوب نہ ہو جائے اور اس کی تعریف کرنے والا اور اس کی برائی کرنے والا دونوں اس کے نزدیک برابر نہ ہو جائیں (نہ تعریف سے اثر لے اور نہ برائی سے)۔ حضرت عبد",""],["ٱللَّٰه","a"],["ؓ کے شاگردوں نے اس کی وضاحت کرتے ہوئے بتایا کہ اس کا مطلب یہ ہے کہ حلال کمائی کے ساتھ فقیری حرام کمائی کی مالداری سے اور ",""],["ٱللَّٰه","a"],[" کی اطاعت کرتے ہوئے چھوٹا بننا ",""],["ٱللَّٰه","a"],[" کی نافرمانی کے ساتھ بڑا بننے سے زیادہ محبوب ہو اور حق بات میں تعریف کرنے والا اور برائی کرنے والا برابر ہو۔",""],[" (4)","s"]]]],"f":[["(4)","Abu Nu'aym in his Hilyah (Vol.1 Pg.132). Ahmad has reported a similar narration, as quoted in Safwatus Safwah (Vol.1 Pg.164)."]]},{"b":[["n",[["حضرت ابن مسعودؓ نے فرمایا اس ",""],["ٱللَّٰه","a"],[" کی قسم جس کے سوا کوئی معبود نہیں! جو بندہ اسلام کی حالت پر صبح اور شام کرتا ہے کوئی دنیاوی مصیبت اس کا نقصان نہیں کر سکتی۔",""],[" (5)","s"]]]],"f":[["(5)","Abu Nu'aym in his Hilyah (Vol.1 Pg.132)."]]},{"b":[["n",[["حضرت حجیرہؒ","b"],[" کہتے ہیں حضرت عبد",""],["ٱللَّٰه","a"],[" بن مسعودؓ جب بیان کے لیے بیٹھتے تو فرماتے تم سب دن اور رات کی گزرگاہ میں ہو، تمہاری عمریں کم ہو رہی ہیں اور سارے اعمال حفاظت سے رکھے جا رہے ہیں اور موت اچانک آنے والی ہے۔ جو خیر بوئے گا وہ اپنی پسند کی چیز کاٹے گا اور جو شر بوئے گا وہ ندامت و حسرت کاٹے گا۔ انسان جیسا بوئے گا ویسا اسے ملے گا (اور ہر انسان کو اس کے مقدر کا ضرور مل کر رہے گا، لہٰذا) سست آدمی کو جو لکھا ہوا ہے وہ اسے مل کر رہے گا اور کوئی تیز آدمی اس سے آگے بڑھ کر اس کے مقدر کا نہیں لے سکتا اور خوب زیادہ کوشش کرنے والا انسان وہ چیز حاصل نہیں کر سکتا جو اس کے مقدر میں نہیں ہے اور جسے کوئی خیر ملتی ہے وہ ",""],["ٱللَّٰه","a"],[" کے دینے سے ہی ملتی ہے اور جس کی کسی شر سے حفاظت ہوتی ہے وہ ",""],["ٱللَّٰه","a"],[" ہی کے کرنے سے ہوتی ہے۔ متقی لوگ ہی سردار ہوتے ہیں اور فقہاء لوگ امت کے قائد ہیں، ان کے ساتھ بیٹھنے سے دین کی سمجھ بڑھتی ہے۔",""],[" (6)","s"]]]],"f":[["(6)","Abu Nu'aym in his Hilyah (Vol.1 Pg.134). Ahmad has reported a similar narration, as quoted in Safwatus Safwah (Vol.1 Pg.161)."]]},{"b":[["n",[["حضرت ابن مسعودؓ فرماتے ہیں تم میں سے ہر ایک مہمان ہے اور اس کے پاس جتنا مال ہے وہ سب اسے عاریت پر ملا ہے اور مہمان نے ہر حال میں آگے جانا ہی ہوتا ہے اور عاریت پر مانگی ہوئی چیز اس کے مالک کو واپس کرنی ہی پڑتی ہے۔",""],[" (7)","s"]]]],"f":[["(7)","Abu Nu'aym in his Hilyah (Vol.1 Pg.134)."]]},{"b":[["n",[["حضرت عبدالرحمٰن بن عبد","b"],["ٱللَّٰه","a"],[" بن مسعودؒ","b"],[" کہتے ہیں کہ ایک آدمی نے میرے والد (حضرت عبد",""],["ٱللَّٰه","a"],[" بن مسعودؓ) کی خدمت میں آ کر عرض کیا کہ مجھے ایسے کارآمد کلمات سکھا دیں جو مختصر ہوں لیکن ان کے معنی زیادہ ہوں۔ فرمایا ",""],["ٱللَّٰه","a"],[" کی عبادت کرو اور اس کے ساتھ کسی کو شریک نہ کرو اور قرآن کے تابع بنو، جدھر جدھر چلے تم بھی ادھر کو اس کے ساتھ چلو اور جو بھی تمہارے پاس حق لے کر آئے تم اسے قبول کرو چاہے وہ دور کا یعنی دشمن ہو اور تمہیں ناپسند ہو اور جو بھی تمہارے پاس باطل اور غلط بات لے کر آئے اسے رد کر دو چاہے وہ لے کر آنے والا تمہارا محبوب اور رشتہ دار یا دوست ہو۔",""],[" (8)","s"]]]],"f":[["(8)","Abu Nu'aym in his Hilyah (Vol.1 Pg.134)."]]},{"b":[["n",[["حضرت ابن مسعودؓ نے فرمایا حق (نفس پر) بھاری ہوتا ہے لیکن اس کا انجام اچھا ہوتا ہے اور باطل ہلکا لگتا ہے لیکن اس کا انجام برا ہوتا ہے اور انسان کی بہت سی خواہشیں ایسی ہوتی ہیں کہ جن کے نتیجے میں انسان کو بڑے لمبے غم اٹھانے پڑتے ہیں۔",""],[" (9)","s"]]]],"f":[["(9)","Abu Nu'aym in his Hilyah (Vol.1 Pg.134)."]]},{"b":[["n",[["حضرت ابن مسعودؓ نے فرمایا کبھی دلوں میں نیک اعمال کا بڑا شوق اور جذبہ ہوتا ہے اور کبھی شوق اور جذبہ بالکل نہیں رہتا، تو جب دل میں شوق اور جذبہ ہو اسے تم لوگ غنیمت سمجھو اور جب شوق اور جذبہ بالکل نہ ہو تو دل کو اس کے حال پر چھوڑ دو۔",""],[" (10)","s"]]]],"f":[["(10)","Abu Nu'aym in his Hilyah (Vol.1 Pg.134)."]]},{"b":[["n",[["حضرت منذرؒ","b"],[" کہتے ہیں کچھ چودھری صاحبان حضرت عبد",""],["ٱللَّٰه","a"],[" بن مسعودؓ کی خدمت میں حاضر ہوئے تو ان کی موٹی موٹی گردنیں اور جسمانی صحت دیکھ کر لوگ تعجب کرنے لگے۔ حضرت عبد",""],["ٱللَّٰه","a"],["ؓ نے فرمایا تمہیں بعض ایسے کافر نظر آئیں گے جن کی جسمانی صحت سب سے زیادہ اچھی ہوگی لیکن ان کے دل سب سے زیادہ بیمار ہوں گے اور تمہیں بعض ایسے مومن ملیں گے جن کے دل سب سے زیادہ تندرست ہوں گے لیکن ان کے جسم سب سے زیادہ بیمار ہوں گے۔ ",""],["ٱللَّٰه","a"],[" کی قسم! اگر تمہارے دل تو بیمار ہوں (ان میں کفر و شرک کی بیماریاں ہوں) لیکن تمہارے جسم خوب صحتمند ہوں تو ",""],["ٱللَّٰه","a"],[" کی نگاہ میں تمہارا درجہ گندگی کے کیڑے سے بھی کم ہوگا۔",""],[" (11)","s"]]]],"f":[["(11)","Abu Nu'aym in his Hilyah (Vol.1 Pg.135)."]]},{"b":[["n",[["حضرت ابن مسعودؓ نے فرمایا ",""],["ٱللَّٰه","a"],[" کی ملاقات کے بغیر مومن کو چین نہیں آ سکتا اور جس کا چین اور راحت ",""],["ٱللَّٰه","a"],[" کی ملاقات میں ہے تو سمجھ لو اس کی ",""],["ٱللَّٰه","a"],[" سے ملاقات ہو گئی۔",""],[" (12)","s"]]]],"f":[["(12)","Abu Nu'aym in his Hilyah (Vol.1 Pg.136)."]]},{"b":[["n",[["حضرت ابن مسعودؓ نے فرمایا تم میں سے کوئی آدمی دین میں کسی زندہ انسان کے پیچھے ہرگز نہ چلے کیونکہ زندہ آدمی کا کیا اعتبار، نہ معلوم کب تک ایمان کی حالت میں رہے اور کب کفر ہو جائے (خود براہ راست قرآن و حدیث سے تم اپنے لیے دینی رہنمائی حاصل کرو اور کسی کے پیچھے نہ چلو، لیکن اگر ایسا نہ کر سکو) اور تم ضرور ہی کسی دوسرے کی اقتداء کرنا چاہو تو پھر ان لوگوں کی اقتداء کرو جو دنیا سے جا چکے ہیں کیونکہ زندہ آدمی کے بارے میں کوئی اطمینان نہیں ہے کہ کب کس فتنے میں مبتلا ہو جائے۔",""]]]],"f":[]},{"b":[["n",[["حضرت ابن مسعودؓ نے فرمایا تم میں سے کوئی آدمی ہرگز امعہ نہ بنے۔ لوگوں نے پوچھا اے ابوعبدالرحمٰن! امعہ کون ہوتا ہے؟ فرمایا امعہ وہ ہوتا ہے (جس کی اپنی عقل سمجھ کچھ نہ ہو اور) یوں کہے کہ میں تو لوگوں کے ساتھ ہوں۔ اگر یہ ہدایت والے راستہ پر چلیں گے تو میں بھی ہدایت والے راستہ پر چلوں گا اور اگر یہ گمراہی والے راستہ پر چلیں گے تو میں بھی گمراہی والے راستہ پر چلوں گا۔ غور سے سنو! تم میں سے ہر آدمی اپنے دل کو اس پر ضرور پکا کر رکھے کہ اگر ساری دنیا کے لوگ بھی کافر ہو جائیں تو بھی وہ کفر اختیار نہیں کرے گا۔",""],[" (13)","s"]]]],"f":[["(13)","Abu Nu'aym in his Hilyah (Vol.1 Pg.136)."]]},{"b":[["n",[["حضرت ابن مسعودؓ نے فرمایا تین باتوں پر میں قسم کھاتا ہوں بلکہ چوتھی بات پر بھی قسم کھا لوں تو میں اس قسم میں سچا ہوں گا۔ جس آدمی کا اسلام میں حصہ ہے اسے ",""],["ٱللَّٰه","a"],[" تعالیٰ اس آدمی جیسا نہیں بنائیں گے جس کا اسلام میں کوئی حصہ نہ ہو اور یہ ہرگز نہیں ہو سکتا کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ کسی بندے سے دنیا میں محبت کریں اور قیامت کے دن اسے کسی دوسرے کے سپرد کر دیں اور آدمی دنیا میں جن لوگوں سے محبت کرے گا قیامت کے دن انہی کے ساتھ آئے گا۔ اور چوتھی بات جس پر میں قسم کھاؤں تو میں سچا ہوں گا وہ یہ ہے کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ دنیا میں جس کی پردہ پوشی کریں گے آخرت میں بھی اس کی پردہ پوشی ضرور کریں گے۔",""],[" (14)","s"]]]],"f":[["(14)","Abu Nu'aym in his Hilyah (Vol.1 Pg.137)."]]},{"b":[["n",[["حضرت عبد",""],["ٱللَّٰه","a"],["ؓ نے فرمایا جو دنیا کو چاہے گا وہ آخرت کا نقصان کرے گا اور جو آخرت کو چاہے گا وہ دنیا کا نقصان کرے گا، لہٰذا ہمیشہ باقی رہنے والی آخرت کی وجہ سے فانی دنیا کا نقصان کر لو (لیکن آخرت کا نہ کرو)۔",""],[" (15)","s"]]]],"f":[["(15)","Abu Nu'aym in his Hilyah (Vol.1 Pg.138)."]]},{"b":[["n",[["حضرت ابن مسعودؓ نے فرمایا سب سے سچی بات ",""],["ٱللَّٰه","a"],[" کی کتاب ہے اور سب سے مضبوط حلقہ تقویٰ کا کلمہ ہے اور سب سے بہترین ملت حضرت ابراہیم علیہ السلام کی ملت ہے اور سب سے عمدہ طریقہ حضرت محمدؐ کا طریقہ ہے اور سب سے بہترین سیرت انبیاء علیہم السلام والی سیرت ہے اور سب سے اعلیٰ بات ",""],["ٱللَّٰه","a"],[" کا ذکر ہے اور بہترین قصے قرآن میں ہیں اور بہترین کام وہ ہیں جن کا انجام بہترین ہو اور سب سے برے کام وہ ہیں جو نئے گھڑے جائیں اور جو مال کم ہو لیکن انسان کی ضروریات کے لیے کافی ہو وہ اس مال سے بہتر ہے جو زیادہ ہو اور انسان کو ",""],["ٱللَّٰه","a"],[" سے اور آخرت سے غافل کر دے۔ اور تم کسی جان کو (برے کاموں سے اور ظلم سے) بچا لو یہ تمہارے لیے اس امارت سے بہتر ہے جس میں تم عدل و انصاف سے کام نہ لے سکو۔ اور موت کے وقت کی ملامت سب سے بری ملامت ہے اور قیامت کے دن کی شرمندگی سب سے بری شرمندگی ہے اور ہدایت ملنے کے بعد گمراہ ہو جانا سب سے بری گمراہی ہے اور دل کا غنا سب سے بہترین غنا ہے (پیسہ پاس نہ ہو لیکن دل غنی ہو) اور سب سے بہترین توشہ تقویٰ ہے اور ",""],["ٱللَّٰه","a"],[" تعالیٰ دل میں جتنی باتیں ڈالتے ہیں ان میں سب سے بہترین بات یقین ہے اور شک کرنا کفر میں شامل ہے اور دل کا اندھا پن سب سے برا اندھا پن ہے اور شراب تمام گناہوں کا مجموعہ ہے اور عورتیں شیطان کا جال ہیں اور جوانی پاگل پن کی ایک قسم ہے اور میت پر نوحہ کرنا جاہلیت کے کاموں میں سے ہے۔ اور بعض لوگ جمعہ میں سب سے آخر میں آتے ہیں اور صرف زبان سے ",""],["ٱللَّٰه","a"],[" کا ذکر کرتے ہیں، دل بالکل متوجہ نہیں ہوتا۔ اور سب سے بڑی خطا جھوٹ بولنا ہے اور مسلمان کو گالی دینا فسق ہے اور اس سے جنگ کرنا کفر ہے اور اس کے مال کا احترام کرنا اسی طرح ضروری ہے جس طرح اس کے خون کا احترام کرنا۔ جو لوگوں کو معاف کرے گا ",""],["ٱللَّٰه","a"],[" اس سے معاف کرے گا، جو غصہ پی جائے ",""],["ٱللَّٰه","a"],[" اسے اجر دے گا اور جو اوروں سے درگزر کرے گا ",""],["ٱللَّٰه","a"],[" اس سے درگزر کرے گا اور جو مصیبت پر صبر کرے گا ",""],["ٱللَّٰه","a"],[" اسے بہت عمدہ بدلہ دیں گے۔ اور سب سے بری کمائی سود کی ہے اور سب سے برا کھانا یتیم کا مال ہے اور خوش قسمت وہ ہے جو دوسروں سے نصیحت حاصل کرے اور بدقسمت وہ ہے جو ماں کے پیٹ میں ازل سے بدبخت ہو گیا ہو اور تم میں سے ہر ایک کو اتنا کافی ہے جس سے اس کے دل میں قناعت پیدا ہو جائے۔ تم میں سے ہر ایک کو بالآخر چار ہاتھ جگہ یعنی قبر میں جانا ہے اور اصل معاملہ آخرت کا ہے اور عمل کا دار و مدار اس کے انجام پر ہے اور سب سے بری روایتیں جھوٹی روایتیں ہیں اور سب سے اعلیٰ موت شہادت والی موت ہے اور جو ",""],["ٱللَّٰه","a"],[" کی آزمائش کو پہچانتا ہے وہ اس پر صبر کرتا ہے اور جو نہیں پہچانتا وہ اس کا انکار کرتا ہے اور جو بڑا بنتا ہے ",""],["ٱللَّٰه","a"],[" اسے نیچا کرتے ہیں۔ جو دنیا سے دوستی کرتا ہے دنیا اس کے قابو میں نہیں آتی۔ جو شیطان کی بات مانے گا وہ ",""],["ٱللَّٰه","a"],[" کی نافرمانی کرے گا اور جو ",""],["ٱللَّٰه","a"],[" کی نافرمانی کرے گا ",""],["ٱللَّٰه","a"],[" اسے عذاب دیں گے۔",""],[" (16)","s"]]]],"f":[["(16)","Abu Nu'aym in his Hilyah (Vol.1 Pg.138)."]]},{"b":[["n",[["حضرت ابن مسعودؓ نے فرمایا جو دنیا میں دکھاوے کی وجہ سے عمل کرے گا ",""],["ٱللَّٰه","a"],[" قیامت کے دن اس کے گناہ اور عیوب لوگوں کو دکھائیں گے اور جو دنیا میں شہرت کے لیے عمل کرے گا ",""],["ٱللَّٰه","a"],[" اس کے گناہ قیامت کے دن لوگوں کو سنائیں گے اور جو بڑا بننے کے لیے خود کو اونچا کرے گا ",""],["ٱللَّٰه","a"],[" اسے نیچا کریں گے اور جو عاجزی کی وجہ سے خود کو نیچا کرے گا ",""],["ٱللَّٰه","a"],[" تعالیٰ اسے بلند کر دیں گے۔",""],[" (17)","s"]]]],"f":[["(17)","Abu Nu'aym in his Hilyah (Vol.1 Pg.138)."]]}]},"206":{"lead":[],"stories":[{"b":[["n",[["حضرت جعفر بن برقانؒ","b"],[" کہتے ہیں ہمیں یہ بات پہنچی کہ حضرت سلمان فارسیؓ فرمایا کرتے تھے کہ مجھے تین آدمیوں پر ہنسی آتی ہے اور تین چیزوں سے رونا آتا ہے۔ ایک تو اس آدمی پر ہنسی آتی ہے جو دنیا کی امیدیں لگا رہا ہے حالانکہ موت اسے تلاش کر رہی ہے۔ دوسرے اس آدمی پر جو غفلت میں پڑا ہوا ہے اور اس سے غفلت نہیں برتی جا رہی یعنی فرشتے اس کا ہر برا عمل لکھ رہے ہیں اور اسے ہر عمل کا بدلہ ملے گا۔ تیسرے منہ بھر کر ہنسنے والے پر جسے معلوم نہیں ہے کہ اس نے اپنے رب کو خوش کر رکھا ہے یا ناراض۔ اور مجھے تین چیزوں سے رونا آتا ہے۔ پہلی چیز محبوب دوستوں یعنی حضرت محمدؐ اور ان کی جماعت کی جدائی، دوسری موت کی سختی کے وقت آخرت کے نظر آنے والے مناظر کی ہولناکی، تیسری ",""],["ٱللَّٰه","a"],[" رب العالمین کے سامنے کھڑا ہونا جبکہ مجھے یہ معلوم نہیں ہوگا کہ میں جہنم میں جاؤں گا یا جنت میں۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Nu'aym in his Hilyah (Vol.1 Pg.207)."]]},{"b":[["n",[["حضرت سلمانؓ نے فرمایا جب ",""],["ٱللَّٰه","a"],[" تعالیٰ کسی بندے کے ساتھ برائی اور ہلاکت کا ارادہ فرماتے ہیں تو اس سے حیا نکال لیتے ہیں جس کا نتیجہ یہ ہوتا ہے کہ تم دیکھو گے کہ لوگ بھی اس سے بغض رکھتے ہیں اور وہ بھی لوگوں سے بغض رکھتا ہے۔ جب وہ ایسا ہو جاتا ہے تو پھر اس سے رحم کرنے اور ترس کھانے کی صفت نکال دی جاتی ہے جس کا نتیجہ یہ ہوتا ہے کہ تم دیکھو گے کہ وہ بداخلاق، اکھڑ طبیعت اور سخت دل ہو گیا ہے۔ جب وہ ایسا ہو جاتا ہے تو پھر اس سے امانتداری کی صفت چھین لی جاتی ہے جس کا نتیجہ یہ ہوتا ہے کہ تم دیکھو گے وہ لوگوں سے خیانت کرتا ہے اور لوگ بھی اس سے خیانت کرتے ہیں۔ جب وہ ایسا ہو جاتا ہے تو پھر اسلام کا پٹہ اس کی گردن سے اتار لیا جاتا ہے اور پھر ",""],["ٱللَّٰه","a"],[" اور اس کی مخلوق بھی اس پر لعنت کرتی ہے اور وہ بھی دوسروں پر لعنت کرتا ہے۔",""],[" (2)","s"]]]],"f":[["(2)","Abu Nu'aym in his Hilyah (Vol.1 Pg.204)."]]},{"b":[["n",[["حضرت سلمانؓ نے فرمایا اس دنیا میں مومن کی مثال اس بیمار جیسی ہے جس کا طبیب اور معالج اس کے ساتھ ہو جو اس کی بیماری اور اس کے علاج دونوں کو جانتا ہو۔ جب اس کا دل کسی ایسی چیز کو چاہتا ہے جس میں اس کی صحت کا نقصان ہو تو معالج اسے اس سے منع کر دیتا ہے اور کہہ دیتا ہے اس کے قریب بھی نہ جاؤ کیونکہ اگر تم نے اسے کھایا تو یہ تمہیں ہلاک کر دے گی۔ اسی طرح وہ معالج اسے نقصان دہ چیز سے روکتا رہتا ہے، یہاں تک کہ وہ بالکل تندرست ہو جاتا ہے اور اس کی بیماری ختم ہو جاتی ہے۔ اسی طرح مومن کا دل بہت سی ایسی دنیاوی چیزوں کو چاہتا رہتا ہے جو دوسروں کو اس سے زیادہ دی گئی ہیں لیکن ",""],["ٱللَّٰه","a"],[" تعالیٰ موت تک اسے ان سے منع کرتے رہتے ہیں اور ان چیزوں کو اس سے دور کرتے رہتے ہیں اور مرنے کے بعد اسے جنت میں داخل کر دیتے ہیں۔",""],[" (3)","s"]]]],"f":[["(3)","Abu Nu'aym in his Hilyah (Vol.1 Pg.207)."]]},{"b":[["n",[["حضرت یحییٰ بن سعیدؒ","b"],[" کہتے ہیں حضرت ابوالدرداءؓ (جو دمشق میں رہتے تھے، انہوں) نے حضرت سلمان فارسیؓ کو خط لکھا کہ آپ (دمشق کی) پاک سرزمین میں تشریف لے آئیں۔ حضرت سلمانؓ نے انہیں جواب میں لکھا کہ زمین کسی کو پاک نہیں بناتی، انسان تو اپنے عمل سے پاک اور مقدس بنتا ہے اور مجھے یہ بات پہنچی ہے کہ آپ کو وہاں طبیب (یعنی قاضی) بنا دیا گیا ہے۔ اگر آپ کے ذریعہ سے بیماروں کو صحت مل رہی ہے یعنی آپ عدل و انصاف والے فیصلے کر رہے ہیں تو پھر تو بہت اچھی بات ہے، شاباش ہو آپ کو۔ اور اگر آپ کو طب نہیں آتی اور زبردستی حکیم و طبیب بنے ہوئے ہیں تو پھر آپ کسی انسان کو (غلط فیصلہ کر کے) مار ڈالنے سے بچیں ورنہ آپ کو جہنم میں جانا ہوگا۔ چنانچہ حضرت ابوالدرداءؓ جب بھی دو آدمیوں میں فیصلہ کرتے اور وہ دونوں پشت پھیر کر جانے لگتے تو انہیں دیکھ کر فرماتے میں تو ",""],["ٱللَّٰه","a"],[" کی قسم! اناڑی حکیم ہوں، تم دونوں میرے پاس آ کر اپنا سارا قصہ دوبارہ سناؤ (یعنی بار بار تحقیق کر کے فیصلہ کرتے)۔",""],[" (4)","s"]]]],"f":[["(4)","Abu Nu'aym in his Hilyah (Vol.1 Pg.205)."]]}]},"207":{"lead":[],"stories":[{"b":[["n",[["حضرت حسان بن عطیہؒ","b"],[" کہتے ہیں حضرت ابوالدرداءؓ فرمایا کرتے تھے تم لوگ اس وقت تک خیر پر رہو گے جب تک کہ تم اپنے بھلے لوگوں سے محبت کرتے رہو گے اور تم میں حق بات کہی جائے اور تم اسے پہچانتے رہو گے کیونکہ حق بات کو پہچاننے والا حق پر عمل کرنے والے کی طرح شمار ہوتا ہے۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Nu'aym in his Hilyah (Vol.1 Pg.210). Bayhaqi and Ibn Asaakir have reported a similar narration, as quoted in Kanzul Ummaal (Vol.8 Pg.224)."]]},{"b":[["n",[["حضرت ابوالدرداءؓ نے فرمایا تم لوگوں کو ان چیزوں کا مکلف نہ بناؤ جن کے وہ (",""],["ٱللَّٰه","a"],[" کی طرف سے) مکلف نہیں ہیں۔ لوگوں کا رب تو ان کا محاسبہ نہ کرے اور تم ان کا محاسبہ کرو، یہ ٹھیک نہیں۔ اے ابن آدم! تو اپنی فکر کر کیونکہ جو لوگوں میں نظر آنے والے عیوب تلاش کرے گا اس کا غم لمبا ہوگا اور اس کا غصہ ٹھنڈا نہیں ہو سکے گا۔",""],[" (2)","s"]]]],"f":[["(2)","Abu Nu'aym in his Hilyah (Vol.1 Pg.211)."]]},{"b":[["n",[["حضرت ابوالدرداءؓ نے فرمایا ",""],["ٱللَّٰه","a"],[" کی عبادت اس طرح کرو کہ گویا تم اسے دیکھ رہے ہو اور اپنے آپ کو مردوں میں شمار کرو اور جان لو کہ تھوڑا مال جو تمہاری ضروریات کے لیے کافی ہو وہ اس زیادہ مال سے بہتر ہے جو تمہیں ",""],["ٱللَّٰه","a"],[" سے غافل کر دے اور یہ بھی جان لو کہ نیکی کبھی پرانی نہیں ہوتی اور گناہ بھلایا نہیں جاتا۔",""],[" (3)","s"]]]],"f":[["(3)","Abu Nu'aym in his Hilyah (Vol.1 Pg.212)."]]},{"b":[["n",[["حضرت ابوالدرداءؓ نے فرمایا خیر یہ نہیں ہے کہ تمہارا مال یا تمہاری اولاد زیادہ ہو جائے بلکہ خیر یہ ہے کہ تمہاری بردباری بڑھ جائے اور تمہارا علم زیادہ ہو اور تم ",""],["ٱللَّٰه","a"],[" کی عبادت میں لوگوں سے آگے نکلنے میں مقابلہ کرو۔ اگر تم نیکی کرو تو ",""],["ٱللَّٰه","a"],[" کی تعریف کرو اور اگر کوئی برا کام ہو جائے تو ",""],["ٱللَّٰه","a"],[" سے استغفار کرو۔",""],[" (4)","s"]]]],"f":[["(4)","Abu Nu'aym in his Hilyah (Vol.1 Pg.212)."]]},{"b":[["n",[["حضرت سالم بن ابی الجعدؒ","b"],[" کہتے ہیں حضرت ابوالدرداءؓ نے فرمایا آدمی کو اس سے بچتے رہنا چاہیے کہ مومنوں کے دل اس سے نفرت کرنے لگ جائیں اور اسے پتہ بھی نہ چلے۔ پھر فرمایا کیا تم جانتے ہو ایسا کیوں ہوتا ہے؟ میں نے کہا نہیں۔ فرمایا بندہ خلوت میں ",""],["ٱللَّٰه","a"],[" کی نافرمانیاں کرتا ہے اس وجہ سے ",""],["ٱللَّٰه","a"],[" تعالیٰ اس کی نفرت مومنوں کے دل میں ڈال دیتے ہیں اور اسے پتہ بھی نہیں چلتا۔",""],[" (5)","s"]]]],"f":[["(5)","Abu Nu'aym in his Hilyah (Vol.1 Pg.215)."]]},{"b":[["n",[["حضرت ابوالدرداءؓ فرماتے تھے ایمان کی چوٹی ",""],["ٱللَّٰه","a"],[" کے فیصلے کی وجہ سے پیش آنے والی تکلیفوں پر صبر کرنا اور تقدیر پر راضی ہونا اور توکل میں مخلص ہونا اور ",""],["ٱللَّٰه","a"],[" کی ہر بات کو بے چون و چرا مان لینا اور ",""],["ٱللَّٰه","a"],[" کے سامنے گردن جھکا دینا ہے۔",""],[" (6)","s"]]]],"f":[["(6)","Abu Nu'aym in his Hilyah (Vol.1 Pg.216)."]]},{"b":[["n",[["حضرت ابوالدرداءؓ فرماتے تھے ہلاکت ہو اس شخص کے لیے جو بہت زیادہ مال جمع کرنے والا ہو اور مال کے لالچ میں اس طرح منہ پھاڑے ہوئے ہو کہ گویا پاگل ہو گیا ہے اور لوگوں کے پاس جو دنیا ہے بس اسے دیکھتا رہتا ہے کہ کسی طرح مجھے مل جائے اور جو اپنے پاس ہے نہ اسے دیکھتا ہے اور نہ اس پر شکر کرتا ہے۔ اگر اس کے بس میں ہو تو رات کو بھی دن سے ملا دے یعنی دن کو تو کماتا ہے، اس کا بس چلے تو وہ رات کو بھی کمایا کرے۔ اس کے لیے ہلاکت ہو، اس کا حساب بھی سخت ہوگا اور اس پر عذاب بھی سخت ہوگا۔",""],[" (7)","s"]]]],"f":[["(7)","Abu Nu'aym in his Hilyah (Vol.1 Pg.217)."]]},{"b":[["n",[["حضرت ابوالدرداءؓ فرماتے تھے اے دمشق والو! کیا تمہیں شرم نہیں آتی؟ اتنا مال جمع کر رہے ہو جسے تم کھا نہیں سکتے اور اتنے گھر بنا رہے ہو جن میں تم رہ نہیں سکتے اور اتنی بڑی امیدیں لگا رہے ہو جن تک تم پہنچ نہیں سکتے۔ اور تم سے پہلے کی قومیں مال جمع کر کے محفوظ کر لیتی تھیں اور انہوں نے بڑی لمبی امیدیں لگا رکھی تھیں اور بڑی مضبوط عمارتیں بنائی تھیں لیکن اب وہ سب ہلاک ہو چکی ہیں اور ان کی امیدیں دھوکہ ثابت ہوئیں اور ان کے گھر قبر بن چکے ہیں۔ یہ قوم عاد ہے جن کے مال اور اولاد سے عدن سے عمان تک کا سارا علاقہ بھرا ہوا تھا لیکن اب مجھ سے عاد کا سارا ترکہ دو درہم میں خریدنے کے لیے کون تیار ہے؟",""],[" (8)","s"]]]],"f":[["(8)","Abu Nu'aym in his Hilyah (Vol.1 Pg.217)."]]},{"b":[["n",[["حضرت عون بن عبد","b"],["ٱللَّٰه","a"],["ؒ","b"],[" کہتے ہیں جب حضرت ابوالدرداءؓ نے دیکھا کہ مسلمانوں نے غوطہ میں نئی عمارتیں بنائی ہیں اور نئے نئے باغات لگائے ہیں تو ان کی مسجد میں کھڑے ہو کر بلند آواز سے اعلان فرمایا اے دمشق والو! تو تمام دمشق والے ان کے پاس جمع ہو گئے۔ انہوں نے ",""],["ٱللَّٰه","a"],[" کی حمد و ثناء بیان کی پھر فرمایا کیا تمہیں شرم نہیں آتی؟ پھر پچھلی حدیث جیسا مضمون ذکر کیا۔",""],[" (9)","s"]]]],"f":[["(9)","Ibn Abi Haatim, as quoted in the Tafseer of Ibn Katheer (Vol.3 Pg.341)."]]},{"b":[["n",[["حضرت صفوان بن عمروؒ","b"],[" کہتے ہیں حضرت ابوالدرداءؓ فرمایا کرتے تھے اے مال والو! اپنے مال کو صدقہ وغیرہ میں خرچ کر کے اپنی کھالوں کے لیے آخرت کی ٹھنڈک کا انتظام کر لو (صدقہ وغیرہ کرنے سے تم لوگ جہنم کی گرمی سے بچ جاؤ گے)۔ مبادا کہ تمہاری موت کا وقت قریب آ جائے اور تمہارے مال میں ہم اور تم برابر ہو جائیں، تم اپنے مال کو دیکھ رہے ہو اور ہم بھی تمہارے ساتھ اسے دیکھ رہے ہیں (اس وقت تم اپنے مال کو صرف دیکھ سکو گے، خرچ نہیں کر سکو گے)۔ حضرت ابوالدرداءؓ نے فرمایا مجھے تم پر اس بات کا ڈر ہے کہ تم چھپی ہوئی خواہش کی وجہ سے نعمت استعمال کرو گے تو وہ نعمت تمہیں غفلت میں ڈال دے گی اور یہ اس وقت ہوگا جب تم کھانا پیٹ بھر کر کھاؤ گے لیکن علم سے بھوکے رہو گے اور اسے کچھ بھی حاصل نہیں کرو گے۔ یہ بھی فرمایا تم میں سب سے بہتر وہ ہے جو اپنے ساتھی سے یہ کہے آ مرنے سے پہلے ہم روزے رکھ لیں اور تم میں سب سے برا وہ ہے جو اپنے ساتھی سے یہ کہے آ مرنے سے پہلے ہم کھا پی لیں اور کھیل تماشا کر لیں۔",""]]]],"f":[]},{"b":[["n",[["ایک دفعہ حضرت ابوالدرداءؓ کا چند لوگوں پر گزر ہوا جو مکان بنا رہے تھے تو ان سے فرمایا تم دنیا میں نئی نئی عمارتیں کھڑی کر رہے ہو حالانکہ ",""],["ٱللَّٰه","a"],[" تو اس کے اجاڑنے کا ارادہ کیے ہوئے ہیں اور ",""],["ٱللَّٰه","a"],[" جس چیز کا ارادہ کر لیتے ہیں اسے وجود میں ضرور لے آتے ہیں اور اس میں کوئی رکاوٹ نہیں بن سکتا۔",""]]]],"f":[]},{"b":[["n",[["حضرت مکحولؒ","b"],[" کہتے ہیں حضرت ابوالدرداءؓ اجاڑ جگہیں تلاش کیا کرتے تھے اور جب کوئی اجاڑ جگہ مل جاتی تو فرماتے اے رہنے والوں کو اجاڑنے والی اجاڑ جگہ! تجھ میں بسنے والے پہلے لوگ کہاں ہیں؟",""],[" (10)","s"]]]],"f":[["(10)","Abu Nu'aym in his Hilyah (Vol.1 Pg.218)."]]},{"b":[["n",[["حضرت ابوالدرداءؓ نے فرمایا تین چیزیں مجھے بہت پسند ہیں لیکن عام لوگوں کو پسند نہیں ہیں: فقر، بیماری اور موت۔ اور یہ بھی فرمایا اپنے رب کی ملاقات کے شوق کی وجہ سے مجھے موت سے محبت ہے اور اپنے رب کے سامنے عاجزی ظاہر کرنے کی وجہ سے مجھے فقر سے محبت ہے اور گناہوں کے لیے کفارہ ہونے کی وجہ سے مجھے بیماری سے محبت ہے۔",""],[" (11)","s"]]]],"f":[["(11)","Abu Nu'aym in his Hilyah (Vol.1 Pg.217)."]]},{"b":[["n",[["حضرت شرحبیلؒ","b"],[" کہتے ہیں حضرت ابوالدرداءؓ جب کوئی جنازہ دیکھتے تو فرماتے تم صبح کو جا رہے ہو شام کو ہم بھی تمہارے پاس آ جائیں گے یا تم شام کو جا رہے ہو، صبح کو ہم بھی آ جائیں گے۔ جنازہ ایک زبردست اور موثر نصیحت ہے لیکن لوگ کتنی جلدی غافل ہو جاتے ہیں۔ نصیحت حاصل کرنے کے لیے موت کافی ہے، ایک ایک کر کے لوگ جا رہے ہیں اور آخر میں ایسے لوگ رہتے جا رہے ہیں جنہیں کچھ سمجھ نہیں ہے (جنازہ دیکھ کر پھر اپنے دنیاوی کاموں میں لگے رہتے ہیں)۔",""],[" (12)","s"]]]],"f":[["(12)","Abu Nu'aym in his Hilyah (Vol.1 Pg.218)."]]},{"b":[["n",[["حضرت عون بن عبد","b"],["ٱللَّٰه","a"],["ؒ","b"],[" کہتے ہیں حضرت ابوالدرداءؓ نے فرمایا جو دوسروں کے حالات معلوم کرے گا اسے اپنی پسند کے حالات نظر نہیں آئیں گے (کیونکہ خیر والے آدمی کم ہوا کرتے ہیں) اور جو پیش آنے والے دردناک حالات کے لیے صبر تیار نہیں کرے گا وہ آخرکار بے بس و عاجز ہو جائے گا۔ اگر تم لوگوں کو برا بھلا کہو گے تو لوگ بھی تمہیں برا بھلا کہیں گے، اگر تم انہیں کہنا چھوڑ دو گے تو وہ تمہیں نہیں چھوڑیں گے۔ حضرت عونؒ نے پوچھا تو اس صورت میں آپ میرے لیے کیا فرماتے ہیں؟ فرمایا لوگ تمہیں برا بھلا کہیں تو تم ان سے بدلہ آج نہ لو بلکہ یہ ان کے ذمہ ادھار رہنے دو، جس دن تمہیں اس بدلہ کی شدید ضرورت ہوگی اس دن ان سے اس کا بدلہ لے لینا یعنی قیامت کے دن۔",""],[" (13)","s"]]]],"f":[["(13)","Abu Nu'aym in his Hilyah (Vol.1 Pg.218)."]]},{"b":[["n",[["حضرت ابوالدرداءؓ نے فرمایا جو موت کو کثرت سے یاد کرے گا اس کا اترانا اور حسد دونوں ختم ہو جائیں گے۔",""],[" (14)","s"]]]],"f":[["(14)","Abu Nu'aym in his Hilyah (Vol.1 Pg.220)."]]},{"b":[["n",[["حضرت ابوالدرداءؓ نے فرمایا کیا بات ہے میں دیکھ رہا ہوں کہ جس روزی کی ",""],["ٱللَّٰه","a"],[" نے ذمہ داری لے رکھی ہے اس کے لیے تو تم بہت فکر اور کوشش کرتے ہو اور جو عمل ",""],["ٱللَّٰه","a"],[" نے تمہارے ذمہ لگائے ہیں انہیں تم ضائع کر رہے ہو۔ جانوروں کا علاج کرنے والا گھوڑوں کو جتنا جانتا ہے میں اس سے زیادہ تمہارے بروں کو جانتا ہوں۔ یہ وہ لوگ ہیں جو نماز وقت گزرنے کے بعد پڑھتے ہیں اور قرآن سنتے تو ہیں لیکن دل سے نہیں سنتے اور غلاموں کو آزاد تو کر دیتے ہیں لیکن وہ پھر بھی آزاد نہیں ہوتے، ان سے غلاموں کی طرح خدمت لیتے رہتے ہیں۔",""],[" (15)","s"]]]],"f":[["(15)","Abu Nu'aym in his Hilyah (Vol.1 Pg.221)."]]},{"b":[["n",[["حضرت ابوالدرداءؓ نے فرمایا زندگی بھر خیر کو تلاش کرتے رہو اور ",""],["ٱللَّٰه","a"],[" کی رحمت کے جھونکوں کے سامنے خود کو لاتے رہو کیونکہ ",""],["ٱللَّٰه","a"],[" کی رحمت کے جھونکے چلتے رہتے ہیں جنہیں ",""],["ٱللَّٰه","a"],[" اپنے جن بندوں پر چاہتے ہیں بھیج دیتے ہیں اور ",""],["ٱللَّٰه","a"],[" سے یہ سوال کرو کہ وہ تمہارے عیبوں پر پردہ ڈالے اور تمہاری خوف کی جگہوں کو امن والا بنائے۔",""],[" (16)","s"]]]],"f":[["(16)","Abu Nu'aym in his Hilyah (Vol.1 Pg.221)."]]},{"b":[["n",[["حضرت عبدالرحمٰن بن جبیر بن نفیرؒ","b"],[" کہتے ہیں ایک آدمی نے حضرت ابوالدرداءؓ کی خدمت میں عرض کیا آپ مجھے کوئی ایسی بات سکھا دیں جس سے ",""],["ٱللَّٰه","a"],[" مجھے نفع دے۔ فرمایا ایک نہیں، دو، تین، چار، بلکہ پانچ باتیں سکھانے کو تیار ہوں جن پر عمل کرنے والے کو ",""],["ٱللَّٰه","a"],[" تعالیٰ بلند درجے عطا فرمائیں گے۔ پھر فرمایا صرف پاکیزہ روزی کھاؤ اور صرف پاکیزہ مال کماؤ اور صرف پاکیزہ روزی گھر میں لاؤ اور ",""],["ٱللَّٰه","a"],[" سے یہ مانگو کہ وہ تمہیں ایک دن میں ایک دن کی روزی عطا فرمائے اور جب تم صبح اٹھو تو اپنے آپ کو مردوں میں شمار کرو گویا کہ تم ان میں جا ملے ہو، اپنی آبرو کو ",""],["ٱللَّٰه","a"],[" کی خاطر قربان کر دو، لہٰذا جو تمہیں برا بھلا کہے یا گالی دے یا تم سے لڑے تم اسے ",""],["ٱللَّٰه","a"],[" کے لیے چھوڑ دو اور جب تم سے کوئی برا کام ہو جائے تو فوراً ",""],["ٱللَّٰه","a"],[" سے استغفار کرو۔",""],[" (17)","s"]]]],"f":[["(17)","Abu Nu'aym in his Hilyah (Vol.1 Pg.222)."]]},{"b":[["n",[["حضرت ابوالدرداءؓ نے فرمایا انسان کا دل دنیا کی محبت میں جوان رہتا ہے اگرچہ بڑھاپے کی وجہ سے اس کی ہنسلی کی دونوں ہڈیاں آپس میں مل جائیں، لیکن جن کے دلوں کو ",""],["ٱللَّٰه","a"],[" نے تقویٰ کے لیے آزما لیا ہے ان کے دل دنیا کی محبت میں جوان نہیں رہتے اور ایسے کامل متقی لوگ بہت کم ہوتے ہیں۔",""],[" (18)","s"]]]],"f":[["(18)","Abu Nu'aym in his Hilyah (Vol.1 Pg.223). Ibn Asaakir has reported a similar narration, as quoted in Kanzul Ummaal (Vol.8 Pg.224)."]]},{"b":[["n",[["حضرت ابوالدرداءؓ نے فرمایا تین کام ایسے ہیں جن کو کرنے سے ابن آدم کے سارے کام قابو میں آ جائیں گے: تم اپنی مصیبت کا کسی سے شکوہ نہ کرو اور اپنی بیماری کسی کو مت بتاؤ اور اپنی زبان سے اپنی خوبیاں بیان نہ کرو اور اپنے آپ کو مقدس اور پاکیزہ نہ سمجھو۔",""],[" (19)","s"]]]],"f":[["(19)","Abu Nu'aym in his Hilyah (Vol.1 Pg.224)."]]},{"b":[["n",[["حضرت ابوالدرداءؓ نے فرمایا مظلوم کی اور یتیم کی بددعا سے بچو کیونکہ ان دونوں کی بددعا رات کو ",""],["ٱللَّٰه","a"],[" کی طرف چلتی ہے جبکہ لوگ سوئے ہوئے ہوتے ہیں۔ ایک روایت میں یہ ہے کہ مجھے لوگوں میں اس پر ظلم کرنا سب سے زیادہ مبغوض ہے جو بالکل بے بس اور بے کس ہو اور ",""],["ٱللَّٰه","a"],[" کے علاوہ کسی اور سے میرے خلاف مدد نہ لے سکے۔",""],[" (20)","s"]]]],"f":[["(20)","Abu Nu'aym in his Hilyah (Vol.1 Pg.221)."]]},{"b":[["n",[["حضرت معمرؒ","b"],[" اپنے ایک ساتھی سے روایت کرتے ہیں کہ حضرت ابوالدرداءؓ نے حضرت سلمانؓ کو خط میں یہ لکھا کہ اے میرے بھائی! اپنی صحت اور فراغت کو اس بلا کے آنے سے پہلے غنیمت سمجھو جس کو تمام بندے مل کر ٹال نہیں سکتے (اس بلا سے مراد موت ہے) اور مصیبت زدہ کی دعا کو غنیمت سمجھو۔ اور اے میرے بھائی! مسجد تمہارا گھر ہونا چاہیے یعنی مسجد میں زیادہ وقت اعمال میں گزارو کیونکہ میں نے حضورؐ کو یہ فرماتے ہوئے سنا کہ مسجد ہر متقی کا گھر ہے اور مسجد جن لوگوں کا گھر ہے ",""],["ٱللَّٰه","a"],[" نے یہ ذمہ داری لے رکھی ہے کہ انہیں خوشی اور راحت نصیب ہوگی اور پل صراط کو پار کر کے ",""],["ٱللَّٰه","a"],[" کی رضامندی حاصل کریں گے۔ اور اے میرے بھائی! یتیم پر رحم کرو اور اسے اپنے قریب کرو اور اسے اپنے کھانے میں سے کھلاؤ کیونکہ ایک مرتبہ ایک آدمی نے حضورؐ کی خدمت میں حاضر ہو کر اپنے دل کی سختی کی شکایت کی تو حضورؐ نے فرمایا کیا تم چاہتے ہو کہ تمہارا دل نرم ہو جائے؟ اس نے کہا جی ہاں۔ حضورؐ نے فرمایا یتیم کو اپنے قریب کر لو، اس کے سر پر ہاتھ پھیرو اور اسے اپنے کھانے میں سے کھلاؤ، اس سے تمہارا دل نرم ہو جائے گا اور تمہاری ہر ضرورت پوری ہوگی۔ اور اے میرے بھائی! اتنا جمع نہ کرو جس کا تم شکر ادا نہ کر سکو کیونکہ میں نے حضورؐ کو فرماتے ہوئے سنا کہ وہ دنیا والا انسان جس نے اس دنیا کے خرچ کرنے میں ",""],["ٱللَّٰه","a"],[" کی اطاعت کی تھی اسے قیامت کے دن اس حال میں لایا جائے گا کہ وہ آگے آگے ہوگا اور اس کا مال اس کے پیچھے ہوگا، وہ جب بھی پل صراط پر لڑکھڑائے گا تو اس کا مال اس سے کہے گا تم بے فکر ہو کر چلتے رہو (تم جہنم میں نہیں گر سکتے کیونکہ) مال کا جو حق تمہارے ذمہ تھا وہ تم نے ادا کیا تھا۔ پھر حضورؐ نے فرمایا جس آدمی نے اس دنیا کے بارے میں ",""],["ٱللَّٰه","a"],[" کی اطاعت نہیں کی تھی اسے اس حال میں لایا جائے گا کہ اس کا مال اس کے کندھے کے درمیان ہوگا اور اس کا مال اسے ٹھوکر مار کر کہے گا تیرا ناس ہو، تو نے میرے بارے میں ",""],["ٱللَّٰه","a"],[" کے حکم پر عمل کیوں نہیں کیا؟ یہ مال اس کے ساتھ بار بار ایسے ہی کرتا رہے گا یہاں تک کہ وہ ہلاکت کو پکارنے لگے گا۔ اور اے میرے بھائی! مجھے یہ بتایا گیا ہے کہ تم نے ایک خادم خریدا ہے حالانکہ میں نے حضورؐ کو فرماتے ہوئے سنا ہے کہ بندہ کا ",""],["ٱللَّٰه","a"],[" سے اور ",""],["ٱللَّٰه","a"],[" کا بندہ سے تعلق اس وقت تک رہتا ہے جب تک کہ اس کی خدمت نہ کی جائے اور جب اس کی خدمت ہونے لگتی ہے تو اس پر حساب واجب ہو جاتا ہے۔ ام درداء نے مجھ سے ایک خادم مانگا اور میں ان دنوں مالدار بھی تھا لیکن میں نے چونکہ حساب والی حدیث سن رکھی تھی اس وجہ سے مجھے خادم خریدنا پسند نہ آیا۔ اور اے میرے بھائی! میرے لیے اور تمہارے لیے کون اس بات کی ضمانت دے سکتا ہے کہ ہم قیامت کے دن ایک دوسرے سے مل سکیں گے اور ہمیں حساب کا کوئی ڈر نہ ہوگا؟ اور اے میرے بھائی! حضورؐ کے صحابی ہونے کی وجہ سے دھوکے میں مت آ جانا کیونکہ ہم نے حضورؐ کے بعد بہت لمبا عرصہ گزار لیا ہے اور ",""],["ٱللَّٰه","a"],[" ہی خوب جانتا ہے کہ ہم نے حضورؐ کے بعد کیا کیا ہے۔",""],[" (21)","s"]]]],"f":[["(21)","Abu Nu'aym in his Hilyah (Vol.1 Pg.224). Ibn Asaakir has reported a similar narration without the portion from \"in fact Ummu Dardaa...\", as quoted in Kanzul Ummaal (Vol.8 Pg.224)."]]},{"b":[["n",[["حضرت عبدالرحمٰن بن محمد محاربیؒ","b"],[" کہتے ہیں مجھے یہ بات پہنچی ہے کہ حضرت ابوالدرداءؓ نے اپنے ایک بھائی کو خط میں یہ لکھا اما بعد! تمہارے پاس جتنی دنیا ہے وہ تم سے پہلے دوسروں کے پاس تھی اور تمہارے بعد پھر دوسروں کے پاس چلی جائے گی۔ اس میں سے تمہاری صرف اتنی ہے جو تم نے اپنے لیے آگے بھیج دی یعنی ",""],["ٱللَّٰه","a"],[" کے نام پر دوسروں پر خرچ کر دی۔ لہٰذا اپنے آپ کو اپنی نیک اولاد پر ترجیح دو یعنی دوسروں پر خرچ کر جاؤ گے تو تمہارے کام آئے گی ورنہ تمہارے بعد تمہاری اولاد کو مل جائے گی، کیونکہ تم ایسی ذات کے پاس پہنچ جاؤ گے جو تمہارا کوئی عذر قبول نہیں کرے گی۔ اور تم ان لوگوں کے لیے جمع کر رہے ہو جو تمہاری کبھی تعریف نہیں کریں گے۔ اور تم دو طرح کے آدمیوں کے لیے جمع کر رہے ہو، یا تو وہ تمہارے مال میں ",""],["ٱللَّٰه","a"],[" کے حکم پر عمل کرے گا اور تم تو اس مال کو دوسروں پر خرچ کرنے کی سعادت حاصل نہ کر سکے لیکن یہ سعادت اسے مل جائے، یا وہ اس مال میں ",""],["ٱللَّٰه","a"],[" کی نافرمانی پر عمل کرے گا اور چونکہ یہ مال تم نے اس کو جمع کر کے دیا ہے اس لیے اس کے غلط خرچ کرنے کا ذریعہ بننے کی وجہ سے تم خود بدبخت بن جاؤ گے۔ بہرحال ",""],["ٱللَّٰه","a"],[" کی قسم! ان دونوں میں سے کوئی بھی اس بات کا حقدار نہیں ہے کہ تم اس کی وجہ سے اپنی کمر پر بوجھ لاد کر اس کی سزا بھگتو۔ لہٰذا تم اسے اپنی ذات پر ترجیح مت دو اور جو جا چکے ہیں ان کے لیے ",""],["ٱللَّٰه","a"],[" کی رحمت کی امید رکھو اور جو باقی رہ گئے ہیں ان کے بارے میں ",""],["ٱللَّٰه","a"],[" کی عطا پر اعتماد کرو۔ والسلام۔",""],[" (22)","s"]]]],"f":[["(22)","Abu Nu'aym in his Hilyah (Vol.1 Pg.216)."]]},{"b":[["n",[["حضرت ابوالدرداءؓ نے حضرت مسلمہ بن مخلدؓ کو خط میں یہ لکھا اما بعد! بندہ جب ",""],["ٱللَّٰه","a"],[" کے حکم پر عمل کرتا ہے تو ",""],["ٱللَّٰه","a"],[" اس سے محبت کرنے لگتے ہیں اور جب ",""],["ٱللَّٰه","a"],[" اس سے محبت کرنے لگتے ہیں تو اس کی محبت اپنی مخلوق میں ڈال دیتے ہیں اور جب بندہ ",""],["ٱللَّٰه","a"],[" کی نافرمانی والا عمل کرتا ہے تو ",""],["ٱللَّٰه","a"],[" اس سے نفرت کرنے لگتے ہیں اور جب ",""],["ٱللَّٰه","a"],[" اس سے نفرت کرنے لگتے ہیں تو اس کی نفرت اپنی مخلوق میں ڈال دیتے ہیں۔",""],[" (23)","s"]]]],"f":[["(23)","Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.8 Pg.225)."]]},{"b":[["n",[["حضرت ابوالدرداءؓ نے فرمایا اسلام صرف بے چوں و چرا حکم ماننے کا نام ہے۔ خیر صرف جماعت میں ہے اور انسان ",""],["ٱللَّٰه","a"],[" اور خلیفہ اور عام مسلمانوں کے ساتھ خیر خواہی کرے۔",""],[" (24)","s"]]]],"f":[["(24)","Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.8 Pg.227)."]]}]},"208":{"lead":[],"stories":[{"b":[["n",[["حضرت سفیان ثوریؒ","b"],[" کہتے ہیں ایک مرتبہ حضرت ابوذر غفاریؓ نے کعبہ کے پاس کھڑے ہو کر فرمایا اے لوگو! میں جندب غفاری ہوں، اس بھائی کے پاس آ جاؤ جو تمہارا خیر خواہ اور بڑا شفیق ہے۔ اس پر لوگوں نے انہیں چاروں طرف سے گھیر لیا تو فرمایا ذرا یہ بتاؤ کہ جب تم میں سے کسی کا سفر کا ارادہ ہوتا ہے تو کیا وہ اتنا سا سب زاد راہ نہیں لیتا جس سے وہ منزل مقصود تک پہنچ جائے؟ لوگوں نے کہا لیتا ہے۔ فرمایا قیامت کا راستہ تو سب سفروں سے لمبا سفر ہے لہٰذا اتنا زاد راہ لے لو جس سے یہ سفر ٹھیک طرح ہو جائے۔ لوگوں نے کہا وہ زاد راہ کیا ہے جس سے ہمارا یہ سفر ٹھیک طرح ہو جائے؟ فرمایا حج کرو اس سے تمہارے بڑے بڑے کام ہو جائیں گے اور سخت گرم دن میں روزے رکھو کیونکہ قیامت کا دن بہت لمبا ہے اور رات کے اندھیرے میں دو رکعت نماز پڑھو، یہ دو رکعتیں قبر کی تنہائی میں کام آئیں گی۔ یا تو خیر کی بات کہو یا چپ رہو، شر کی بات مت کرو کیونکہ ایک بہت بڑے دن میں ",""],["ٱللَّٰه","a"],[" کے سامنے کھڑے ہونا ہے۔ اپنا مال صدقہ کرو تاکہ قیامت کی مشکلات سے نجات پا سکو۔ اس دنیا میں دو باتوں کے لیے کسی مجلس میں بیٹھو، یا تو آخرت کی تیاری کے لیے یا حلال روزی حاصل کرنے کے لیے۔ ان دو کاموں کے علاوہ کسی اور کام کے لیے مجلس میں بیٹھنے سے تمہارا نقصان ہوگا، فائدہ نہیں ہوگا، ایسی مجلس کا ارادہ بھی نہ کرو۔ مال کے دو حصے کرو، ایک حصہ اپنے اہل و عیال پر خرچ کرو اور دوسرا حصہ اپنی آخرت کے لیے آگے بھیج دو۔ ان دو جگہوں کے علاوہ کہیں اور خرچ کرو گے تو اس سے تمہارا نقصان ہوگا، فائدہ نہیں ہوگا، لہٰذا اس کا ارادہ بھی نہ کرو۔ پھر حضرت ابوذرؓ نے بلند آواز سے فرمایا اے لوگو! دنیا کے لالچ نے تمہیں مار ڈالا اور تم جتنا لالچ کرتے ہو اسے تم کبھی حاصل نہیں کر سکتے۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Nu'aym in his Hilyah (Vol.1 Pg.165)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن محمدؒ","b"],[" کہتے ہیں میں نے ایک قابل اعتماد انسان کو یہ کہتے ہوئے سنا کہ ہمیں یہ بات پہنچی ہے کہ حضرت ابوذرؓ فرمایا کرتے تھے اے لوگو! میں تمہارا خیر خواہ اور بڑا شفیق ہوں۔ رات کے اندھیرے میں نماز پڑھا کرو، یہ نماز قبر کی تنہائی میں کام آئے گی۔ دنیا میں روزے رکھو، قبروں سے اٹھائے جانے کے دن کی گرمی میں کام آئیں گے اور دشوار دن سے ڈر کر صدقہ دیا کرو۔ اے لوگو! میں تمہارا خیر خواہ اور بڑا شفیق ہوں۔",""],[" (2)","s"]]]],"f":[["(2)","Abu Nu'aym in his Hilyah (Vol.1 Pg.165)."]]},{"b":[["n",[["حضرت ابوذرؓ نے فرمایا لوگوں کے ہاں بچے پیدا ہوتے ہیں جو ایک دن مر جائیں گے اور لوگ عمارتیں بناتے ہیں جو ایک دن گر جائیں گی۔ لوگوں کو فانی دنیا کا بڑا شوق ہے اور ہمیشہ رہنے والی آخرت کو چھوڑ دیتے ہیں۔ غور سے سنو! دو چیزیں عام لوگوں کو ناپسند ہیں لیکن ہیں وہ بہت اچھی، ایک موت اور دوسرا فقر۔",""],[" (3)","s"]]]],"f":[["(3)","Abu Nu'aym in his Hilyah (Vol.1 Pg.163)."]]},{"b":[["n",[["حضرت حبان بن ابی جبلہؒ","b"],[" کہتے ہیں حضرت ابوالدرداءؓ نے فرمایا تمہارے بچے پیدا ہو رہے ہیں جو ایک دن مر جائیں گے اور تم عمارتیں بنا رہے ہو جو ایک دن اجڑ جائیں گی۔ فانی دنیا کے تم حریص ہو لیکن باقی رہنے والی آخرت کو چھوڑ دیتے ہو۔ غور سے سنو! تین چیزیں لوگوں کو پسند نہیں ہیں لیکن ہیں بہت اچھی، ایک موت، دوسرے بیماری، تیسرے فقر۔",""],[" (4)","s"]]]],"f":[["(4)","Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.8 Pg.224)."]]}]},"209":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوطفیلؒ","b"],[" کہتے ہیں میں نے حضرت حذیفہؓ کو یہ فرماتے ہوئے سنا کہ اے لوگو! اور لوگ تو حضورؐ سے خیر کے بارے میں پوچھا کرتے تھے لیکن میں شر کے بارے میں پوچھا کرتا تھا، تو کیا تم لوگ زندوں میں سے مردہ کے بارے میں نہیں پوچھتے؟ پھر فرمایا ",""],["ٱللَّٰه","a"],[" تعالیٰ نے حضرت محمدؐ کو مبعوث فرمایا، انہوں نے لوگوں کو گمراہی سے ہدایت کی طرف اور کفر سے ایمان کی طرف بلایا، پھر جس کا مقدر اچھا تھا اس نے حضورؐ کی دعوت کو قبول کر لیا اور جو لوگ مردہ تھے وہ حق کو قبول کر کے زندہ ہو گئے اور جو زندہ تھے وہ باطل پر چلتے رہنے کی وجہ سے مردہ ہو گئے۔ پھر (حضورؐ کے انتقال سے) نبوت چلی گئی، پھر نبوت کی نہج پر خلافت آ گئی۔ اب اس کے بعد ظلم والی بادشاہت ہوگی۔ جو ان کے ظلم پر دل، زبان اور ہاتھ سے انکار کرے گا تو وہ پورے حق پر عمل کرنے والا ہوگا اور جو ہاتھ کو روک لے گا اور صرف دل اور زبان سے انکار کرے گا وہ حق کے ایک حصہ کو چھوڑنے والا ہوگا اور جو ہاتھ اور زبان کو روک لے گا اور صرف دل سے انکار کرے گا وہ حق کے دو حصوں کو چھوڑنے والا ہوگا اور جو دل سے بھی انکار نہیں کرے گا وہ انسان زندوں میں سے مردہ ہے۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Nu'aym in his Hilyah (Vol.1 Pg.274)."]]},{"b":[["n",[["حضرت حذیفہؓ نے فرمایا دل چار قسم کے ہوتے ہیں۔ ایک وہ دل جس پر پردہ پڑا ہوا ہے، یہ تو کافر کا دل ہے۔ دوسرا دو منہ والا دل، یہ منافق کا دل ہے۔ تیسرا صاف ستھرا دل جس میں چراغ روشن ہے، یہ مومن کا دل ہے۔ چوتھا وہ دل جس میں نفاق بھی ہے اور ایمان بھی۔ ایمان کی مثال درخت جیسی ہے جو عمدہ پانی سے بڑھتا ہے اور نفاق کی مثال پھوڑے جیسی ہے جو پیپ اور خون سے بڑھتا ہے۔ ایمان اور نفاق میں سے جس کی صفات غالب آ جائیں گی وہی غالب آ جائے گا۔",""],[" (2)","s"]]]],"f":[["(2)","Abu Nu'aym in his Hilyah (Vol.1 Pg.276)."]]},{"b":[["n",[["حضرت حذیفہؓ نے فرمایا فتنہ دلوں پر ڈالا جاتا ہے تو جس دل میں وہ فتنہ پوری طرح داخل ہو جاتا ہے اس میں ایک کالا نقطہ لگ جاتا ہے اور جو دل اس فتنہ سے انکار کرتا ہے اس میں سفید نقطہ لگ جاتا ہے۔ اب تم میں سے جو یہ جاننا چاہتا ہے کہ اس پر فتنہ کا اثر پڑا ہے یا نہیں، وہ یہ دیکھے کہ جس چیز کو پہلے وہ حلال سمجھتا تھا اب اسے حرام سمجھنے لگ گیا ہے یا جس چیز کو وہ پہلے حرام سمجھتا تھا اب اسے حلال سمجھنے لگ گیا ہے تو بس سمجھ لے کہ اس پر فتنہ کا پورا اثر ہو گیا ہے۔",""],[" (3)","s"]]]],"f":[["(3)","Abu Nu'aym in his Hilyah (Vol.1 Pg.272)."]]},{"b":[["n",[["حضرت حذیفہؓ نے فرمایا فتنوں سے بچ کر رہو اور کوئی آدمی خود اٹھ کر فتنے کی طرف نہ جائے کیونکہ ",""],["ٱللَّٰه","a"],[" کی قسم! جو بھی از خود اٹھ کر فتنوں کی طرف جائے گا اسے فتنے ایسے بہا کر لے جائیں گے جیسے سیلاب کوڑے کے ڈھیروں کو بہا کر لے جاتا ہے۔ فتنہ جب آتا ہے تو بالکل حق جیسا لگتا ہے یہاں تک کہ جاہل کہتا ہے کہ یہ تو حق جیسا ہے (اس وجہ سے لوگ فتنہ میں مبتلا ہو جاتے ہیں) لیکن جب جاتا ہے تو اس وقت صاف پتہ چل جاتا ہے کہ یہ تو فتنہ تھا۔ لہٰذا جب تم فتنہ کو دیکھو تو اس سے بچ کر رہو اور گھروں میں بیٹھ جاؤ اور تلواریں توڑ ڈالو اور کمان کی تانت کے ٹکڑے کر دو۔",""],[" (4)","s"]]]],"f":[["(4)","Abu Nu'aym in his Hilyah (Vol.1 Pg.273)."]]},{"b":[["n",[["حضرت حذیفہؓ نے فرمایا فتنے رک جاتے ہیں اور پھر اچانک شروع ہو جاتے ہیں، اس لیے اس کی پوری کوشش کرو کہ تمہیں ان دنوں میں موت آ جائے جن دنوں فتنہ رکا ہوا ہو (مرنے کی کوشش سے مراد مرنے کی تمنا اور اس کی دعا ہے)۔",""],[" (5)","s"]]]],"f":[["(5)","Abu Nu'aym in his Hilyah (Vol.1 Pg.274)."]]},{"b":[["n",[["حضرت حذیفہؓ نے فرمایا فتنہ تین قسم کے آدمیوں کے ذریعہ سے آتا ہے۔ ایک تو اس ماہر اور طاقتور عالم کے ملحد ہو جانے کے ذریعہ سے جو اٹھنے والی ہر چیز کا تلوار کے ذریعہ سے قلع قمع کر دیتا ہے، دوسرے اس بیان کرنے والے کے ذریعہ سے جو فتنہ کی دعوت دیتا ہے، تیسرے سردار اور حاکم کے ذریعہ سے۔ عالم اور بیان کرنے والے کو تو فتنہ منہ کے بل گرا دیتا ہے، البتہ سردار کو فتنہ خوب کریدتا ہے اور پھر جو کچھ اس کے پاس ہوتا ہے اس سب کو فتنہ میں مبتلا کر دیتا ہے۔",""],[" (6)","s"]]]],"f":[["(6)","Abu Nu'aym in his Hilyah (Vol.1 Pg.274)."]]},{"b":[["n",[["حضرت حذیفہؓ نے فرمایا فتنہ خالص شراب سے زیادہ عقل کو لے جاتا ہے۔",""],[" (7)","s"]]]],"f":[["(7)","Abu Nu'aym in his Hilyah (Vol.1 Pg.274)."]]},{"b":[["n",[["حضرت حذیفہؓ نے فرمایا لوگوں پر ایسا زمانہ آئے گا کہ اس زمانہ میں فتنوں سے صرف وہی آدمی نجات حاصل کر سکے گا جو ڈوبنے والے کی طرح دعا کرے گا۔",""],[" (8)","s"]]]],"f":[["(8)","Abu Nu'aym in his Hilyah (Vol.1 Pg.274)."]]},{"b":[["n",[["حضرت اعمشؒ","b"],[" کہتے ہیں مجھے یہ بات پہنچی ہے کہ حضرت حذیفہؓ فرمایا کرتے تھے کہ تم میں وہ لوگ سب سے بہترین نہیں ہیں جو دنیا کو آخرت کی وجہ سے یا آخرت کو دنیا کی وجہ سے چھوڑ دیتے ہیں، بلکہ سب سے بہترین لوگ وہ ہیں جو دنیا اور آخرت دونوں کے لیے محنت کرتے ہیں۔",""],[" (9)","s"]]]],"f":[["(9)","Abu Nu'aym in his Hilyah (Vol.1 Pg.278)."]]}]},"210":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوالعالیہؒ","b"],[" کہتے ہیں ایک آدمی نے حضرت ابی بن کعبؓ کی خدمت میں عرض کیا مجھے کچھ وصیت فرما دیں۔ فرمایا ",""],["ٱللَّٰه","a"],[" کی کتاب کو امام بنا لو اور اس کے قاضی اور فیصلہ کرنے والا حکم ہونے پر راضی رہو کیونکہ اسی کو تمہارے رسولؐ تمہارے لیے پیچھے چھوڑ کر گئے ہیں۔ یہ ایسا سفارشی ہے جس کی سفارش مانی جاتی ہے اور ایسا گواہ ہے جس پر کوئی تہمت نہیں لگائی جا سکتی۔ اس میں تمہارا اور تم سے پہلے لوگوں کا تذکرہ ہے اور اس میں تمہارے آپس کے جھگڑوں کا فیصلہ ہے اور اس میں تمہارے بعد والوں کے حالات ہیں۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Nu'aym in his Hilyah (Vol.1 Pg.253)."]]},{"b":[["n",[["حضرت ابی بن کعبؓ نے فرمایا جو بندہ بھی کسی چیز کو ",""],["ٱللَّٰه","a"],[" کے لیے چھوڑ دیتا ہے ",""],["ٱللَّٰه","a"],[" اس کے بدلے میں اس سے بہتر چیز اسے وہاں سے دیتے ہیں جہاں سے ملنے کا اسے گمان نہیں ہوتا اور جو بندہ کسی چیز کو ہلکا سمجھ کر اسے وہاں سے لے لیتا ہے جہاں سے لینا ٹھیک نہیں تو پھر ",""],["ٱللَّٰه","a"],[" تعالیٰ اسے اس سے زیادہ سخت چیز وہاں سے دیتے ہیں جہاں سے ملنے کا اسے گمان بھی نہیں ہوتا۔",""],[" (2)","s"]]]],"f":[["(2)","Abu Nu'aym in his Hilyah (Vol.1 Pg.253)."]]},{"b":[["n",[["حضرت ابی بن کعبؓ نے فرمایا مومن چار حالتوں کے درمیان رہتا ہے۔ اگر کسی تکلیف میں مبتلا ہوتا ہے تو صبر کرتا ہے اور اگر کوئی نعمت ملتی ہے تو شکر کرتا ہے اور اگر بات کرتا ہے تو سچ بولتا ہے اور اگر کوئی فیصلہ کرتا ہے تو انصاف والا فیصلہ کرتا ہے۔ اور ایسے مومن کے بارے میں ",""],["ٱللَّٰه","a"],[" تعالیٰ نے فرمایا ہے",""]]],["q",[["نُورٌ عَلَىٰ نُورٍ","a"]]],["p",[["ترجمہ: \"نور پر نور۔\" (سورۂ نور، آیت 35)۔ یہ مومن پانچ قسم کے نوروں میں چلتا پھرتا ہے۔ اس کا کلام نور ہے اور اس کا علم نور ہے۔ یہ اندر جاتا ہے تو نور میں جاتا ہے، یہ باہر نکلتا ہے تو نور سے باہر نکلتا ہے اور قیامت کے دن یہ نور ہی کی طرف لوٹ کر جائے گا۔ اور کافر پانچ قسم کی ظلمتوں (اندھیروں) میں چلتا پھرتا ہے، اس کا کلام ظلمت ہے، اس کا علم ظلمت ہے، اندر جاتا ہے تو ظلمت میں اور باہر آتا ہے تو ظلمت سے اور قیامت کے دن یہ بے شمار ظلمتوں کی طرف لوٹ کر جائے گا۔",""],[" (3)","s"]]]],"f":[["(3)","Abu Nu'aym in his Hilyah (Vol.1 Pg.255)."]]},{"b":[["n",[["حضرت ابونضرہؒ","b"],[" کہتے ہیں ایک آدمی کو جبر یا جویبر کہا جاتا تھا، انہوں نے کہا میں نے حضرت عمرؓ کے زمانہ خلافت میں ان سے ایک باندی لینے کا ارادہ کیا۔ میں سفر کر کے رات کے وقت مدینہ پہنچا۔ مجھے ",""],["ٱللَّٰه","a"],[" تعالیٰ نے بڑی ذہانت اور بات کرنے کا بڑا سلیقہ عطا فرمایا ہوا ہے۔ میں حضرت عمرؓ کی خدمت میں گیا اور دنیا کے بارے میں بات شروع کی اور دنیا کے چھوٹے ہونے کو بیان کرنے لگا اور اس کا حال ایسا بنا کر چھوڑا کہ گویا دنیا کسی چیز کے برابر نہیں ہے۔ حضرت عمرؓ کے پہلو میں ایک صاحب بیٹھے ہوئے تھے، جب میں بات پوری کر چکا تو انہوں نے فرمایا تمہاری ساری بات تقریباً ٹھیک تھی لیکن تم نے دنیا کی جو برائی بیان کی یہ ٹھیک نہ تھا۔ اور تم جانتے ہو کہ دنیا کیا ہے؟ دنیا کے ذریعہ سے تو ہم جنت تک پہنچیں گے اور یہی آخرت کے لیے زاد راہ ہے اور دنیا ہی میں تو تمہارے وہ اعمال ہیں جن کا بدلہ تم کو آخرت میں ملے گا۔ غرضیکہ انہوں نے دنیا کے بارے میں جو بات کرنی شروع کی تو پتہ چلا کہ یہ تو دنیا کو مجھ سے زیادہ جانتے ہیں۔ میں نے عرض کیا اے امیر المومنین! یہ آپ کے پہلو میں بیٹھے ہوئے صاحب کون ہیں؟ فرمایا یہ مسلمانوں کے سردار حضرت ابی بن کعبؓ ہیں۔",""],[" (4)","s"]]]],"f":[["(4)","Bukhaari in his Adab, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.132)."]]},{"b":[["n",[["ایک آدمی نے حضرت ابی بن کعبؓ کی خدمت میں عرض کیا اے ابوالمنذر! آپ مجھے کچھ وصیت فرما دیں۔ فرمایا لایعنی کام میں ہرگز نہ لگو اور دشمن سے کنارہ کش رہو اور دوست کے ساتھ چوکنے ہو کر چلو (دوستی میں تم سے غلط کام نہ کروا لے)۔ زندہ آدمی کی ان ہی باتوں پر رشک کرو جن پر مر جانے والے پر رشک کرتے ہو یعنی نیک اعمال اور اچھی صفات پر۔ اور اپنی حاجت اس آدمی سے طلب نہ کرو جسے تمہاری حاجت پوری کرنے کی پرواہ نہیں ہے۔",""],[" (5)","s"]]]],"f":[["(5)","Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.8 Pg.224)."]]}]},"211":{"lead":[],"stories":[{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن دینار بہرانیؒ","b"],[" کہتے ہیں حضرت زید بن ثابتؓ نے حضرت ابی بن کعبؓ کو خط میں یہ لکھا اما بعد! ",""],["ٱللَّٰه","a"],[" تعالیٰ نے زبان کو دل کا ترجمان بنایا اور دل کو خزانہ اور حکمران بنایا۔ دل جو حکم دیتا ہے زبان اسے پورا کرتی ہے، جب دل زبان کی موافقت پر ہوتا ہے تو گفتگو مرتب اور مناسب ہوتی ہے اور نہ زبان سے کوئی لغزش ہوتی ہے اور نہ وہ ٹھوکر کھاتی ہے۔ اور جس انسان کا دل اس کی زبان سے پہلے نہ ہو یعنی دل اس کی نگرانی اور دیکھ بھال نہ کرے تو اس کی بات عقل و سمجھ والی نہیں ہوگی۔ جب آدمی اپنی زبان کو بات کرنے میں کھلا اور آزاد چھوڑ دے گا اور زبان دل کی مخالفت کرے گی تو اس طرح وہ آدمی اپنی ناک کاٹ ڈالے گا یعنی خود کو ذلیل کر لے گا۔ اور جب آدمی اپنے قول کا اپنے فعل سے موازنہ کرے گا تو عملی صورت سے ہی اس کے قول کی تصدیق ہوگی۔ اور یہ کہاوت عام طور سے بیان کی جاتی ہے کہ جو بخیل بھی تمہیں ملے گا وہ باتوں میں تو سخی ہوگا لیکن عمل میں بالکل کنجوس ہوگا، اس کی وجہ یہ ہے کہ اس کی زبان اس کے دل سے آگے رہتی ہے یعنی بولتی بہت ہے اور دل کے قابو میں نہیں ہے۔ اور یہ کہاوت بھی عام طور سے بیان کی جاتی ہے کہ جب کوئی آدمی اپنے کہے کی پابندی نہ کرے یعنی اس پر عمل نہ کرے حالانکہ اس بات کو کہتے وقت وہ جانتا تھا کہ یہ بات حق ہے اور اس پر عمل کرنا واجب ہے تو کیا تم اس کے پاس شرف و عزت اور مردانگی پاؤ گے؟ اور آدمی کو چاہیے کہ وہ لوگوں کے عیبوں کو نہ دیکھے کیونکہ جو لوگوں کے عیب دیکھتا ہے اور اپنے عیبوں کو ہلکا سمجھتا ہے وہ اس آدمی کی طرح ہے جو بتکلف ایسا کام کر رہا ہے جس کا اسے حکم نہیں دیا گیا۔ والسلام۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.8 Pg.224)."]]}]},"212":{"lead":[],"stories":[{"b":[["n",[["حضرت ابن عباسؓ نے فرمایا اے گناہ کرنے والے! گناہ کے برے انجام سے مطمئن نہ ہو جانا کیونکہ گناہ کرنے کے بعد بعض ایسی باتیں ہوتی ہیں جو گناہ سے بھی بڑی ہوتی ہیں۔ گناہ کرتے ہوئے تمہیں اپنے دائیں بائیں کے فرشتوں سے شرم نہ آئے تو تم نے جو گناہ کیا ہے یہ اس سے بھی زیادہ بڑا گناہ ہے۔ تمہیں معلوم نہیں ہے کہ ",""],["ٱللَّٰه","a"],[" تمہارے ساتھ کیا کریں گے اور پھر تم ہنستے ہو، تمہارا یہ ہنسنا گناہ سے بھی بڑا ہے اور جب تمہیں گناہ کرنے میں کامیابی حاصل ہو جاتی ہے اور تم اس گناہ پر خوش ہوتے ہو تو تمہاری یہ خوشی اس گناہ سے بھی بڑی ہے اور جب تم گناہ نہ کر سکو اور اس پر تم غمگین ہو جاؤ تو تمہارا یہ غمگین ہونا اس گناہ کے کر لینے سے زیادہ بڑا ہے۔ گناہ کرتے ہوئے ہوا کے چلنے سے تمہارے دروازے کا پردہ ہل جائے تو اس سے ڈرتے ہو اور ",""],["ٱللَّٰه","a"],[" تمہیں دیکھ رہا ہے اس سے تمہارا دل پریشان نہیں ہوتا تو یہ کیفیت اس گناہ کے کر لینے سے زیادہ بڑا گناہ ہے۔ ہائے افسوس! تمہارا بھلا ہو، کیا تم جانتے ہو حضرت ایوب علیہ السلام سے کیا چوک ہوئی تھی جس کی وجہ سے ",""],["ٱللَّٰه","a"],[" نے ان کے جسم کو ایک بیماری میں مبتلا کر دیا تھا اور ان کا سارا مال ختم کر دیا تھا؟ ان سے چوک یہ ہوئی تھی کہ ایک مسکین پر ظلم ہو رہا تھا، اس مسکین نے حضرت ایوبؑ سے مدد مانگی تھی اور کہا تھا کہ یہ ظلم رکوا دیں۔ حضرت ایوبؑ نے اس کی مدد نہیں کی تھی اور ظالم کو اس مسکین پر ظلم کرنے سے نہیں روکا تھا، اس پر ",""],["ٱللَّٰه","a"],[" نے انہیں اس آزمائش میں ڈال دیا تھا۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Nu'aym in his Hilyah (Vol.1 Pg.324). Ibn Asaakir has reported a similar narration from Ibn Abbaas up to the word \"Alas!\", as quoted in Kanzul Ummaal (Vol.2 Pg.248)."]]},{"b":[["n",[["حضرت ابن عباسؓ نے فرمایا فرائض کا اہتمام کرو اور ",""],["ٱللَّٰه","a"],[" نے اپنے جو حق تمہارے ذمے لگائے ہیں انہیں ادا کرو اور ان کی ادائیگی میں ",""],["ٱللَّٰه","a"],[" سے مدد مانگو کیونکہ جب ",""],["ٱللَّٰه","a"],[" کو کسی بندے کے بارے میں پتہ چلتا ہے کہ وہ سچی نیت سے اور ",""],["ٱللَّٰه","a"],[" کے ہاں جو ثواب ہے اسے حاصل کرنے کے شوق میں عمل کر رہا ہے تو اس سے ناگواریاں ضرور ہٹا دیتے ہیں اور ",""],["ٱللَّٰه","a"],[" حقیقی بادشاہ ہیں، جو چاہتے ہیں کرتے ہیں۔",""],[" (2)","s"]]]],"f":[["(2)","Abu Nu'aym in his Hilyah (Vol.1 Pg.326)."]]},{"b":[["n",[["حضرت ابن عباسؓ نے فرمایا ",""],["ٱللَّٰه","a"],[" تعالیٰ نے ہر مومن اور فاجر بندے کے لیے حلال روزی مقرر فرما رکھی ہے، اگر وہ اس روزی کے آنے تک صبر کرتا ہے تو ",""],["ٱللَّٰه","a"],[" اسے حلال روزی دیتے ہیں اور اگر وہ بے صبری کرتا ہے اور حرام میں سے کچھ لے لیتا ہے تو ",""],["ٱللَّٰه","a"],[" اس کی اتنی حلال روزی کم کر دیتے ہیں۔",""],[" (3)","s"]]]],"f":[["(3)","Abu Nu'aym in his Hilyah (Vol.1 Pg.326)."]]}]},"213":{"lead":[],"stories":[{"b":[["n",[["حضرت ابن عمرؓ نے فرمایا بندے کو جب بھی دنیا کی کوئی چیز ملتی ہے تو اس کی وجہ سے ",""],["ٱللَّٰه","a"],[" کے ہاں اس کا درجہ کم ہو جاتا ہے اگرچہ وہ ",""],["ٱللَّٰه","a"],[" کے ہاں عزت و شرف والا ہو۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Nu'aym in his Hilyah (Vol.1 Pg.306)."]]},{"b":[["n",[["حضرت ابن عمرؓ نے فرمایا بندہ اس وقت تک ایمان کی حقیقت کو نہیں پہنچ سکتا جب تک کہ آخرت پر دنیا کو ترجیح دینے کی وجہ سے لوگوں کو کم عقل نہ سمجھے۔",""],[" (2)","s"]]]],"f":[["(2)","Abu Nu'aym in his Hilyah (Vol.1 Pg.306)."]]},{"b":[["n",[["حضرت مجاہدؒ","b"],[" کہتے ہیں میں حضرت ابن عمرؓ کے ساتھ چلا جا رہا تھا کہ اتنے میں ان کا ایک ویران جگہ پر گزر ہوا۔ انہوں نے مجھ سے فرمایا تم یہ کہو اے ویرانے! تیرے ہاں رہنے والوں کا کیا بنا؟ میں نے کہا اے ویرانے! تیرے ہاں رہنے والوں کا کیا بنا؟ حضرت ابن عمرؓ نے فرمایا وہ سب خود تو چلے گئے البتہ ان کے اعمال باقی رہ گئے۔",""],[" (3)","s"]]]],"f":[["(3)","Abu Nu'aym in his Hilyah (Vol.1 Pg.312)."]]}]},"214":{"lead":[],"stories":[{"b":[["n",[["حضرت وہب بن کیسانؒ","b"],[" کہتے ہیں حضرت عبد",""],["ٱللَّٰه","a"],[" بن زبیرؓ نے مجھے یہ نصیحت لکھ کر بھیجی۔ اما بعد! تقویٰ والے لوگوں کی کچھ نشانیاں ہوتی ہیں جن سے وہ پہچانے جاتے ہیں اور وہ خود بھی جانتے ہیں کہ ان کے اندر یہ نشانیاں ہیں اور وہ نشانیاں یہ ہیں: مصیبت پر صبر کرنا، تقدیر پر راضی رہنا، نعمتوں پر شکر کرنا اور قرآن کے حکم کے سامنے جھک جانا۔ امام کی مثال بازار جیسی ہے، جو چیز بازار میں چلتی ہے اور جس کا رواج ہوتا ہے وہی چیز بازار میں لائی جاتی ہے، اسی طرح امام کے پاس اگر حق کا رواج چل پڑے تو اس کے پاس حق ہی لایا جائے گا اور حق والے ہی اس کے پاس آئیں گے اور اگر اس کے پاس باطل کا رواج چل پڑے تو باطل والے ہی اس کے پاس آئیں گے اور باطل ہی اس کے پاس چلے گا۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Nu'aym in his Hilyah (Vol.1 Pg.336)."]]}]},"215":{"lead":[],"stories":[{"b":[["n",[["حضرت حسن بن علیؓ نے فرمایا جو دنیا کو طلب کرتا ہے دنیا اسے لے بیٹھتی ہے اور جو دنیا سے بے رغبتی اختیار کر لیتا ہے تو اسے اس کی پرواہ بھی نہیں ہوتی کہ کون دنیا استعمال کر رہا ہے۔ دنیا کی طلب والا اس آدمی کا غلام ہوتا ہے جو دنیا کا مالک ہوتا ہے اور جس کے دل میں دنیا کی طلب نہیں ہوتی اسے تھوڑی دنیا کافی ہو جاتی ہے اور جس کے دل میں طلب ہوتی ہے اسے ساری دنیا بھی مل جائے تو بھی اس کا کام نہیں چلتا۔ اور جس کا آج کا دن اپنے اعتبار سے کل گزشتہ کی طرح ہے تو وہ دھوکے میں ہے اور جس کا آج کا دن کل آئندہ سے بہتر ہے یعنی کل آئندہ میں اس کی دینی حالت آج سے خراب ہو گئی تو وہ سخت نقصان میں ہے اور جو اپنی ذات کے بارے میں نقصان کی چھان بین نہیں کرتا تو وہ بھی نقصان میں چل رہا ہے اور جو نقصان میں ہے اس کا مر جانا ہی بہتر ہے۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Najjaar, as quoted in Kanzul Ummaal (Vol.8 Pg.222)."]]},{"b":[["n",[["حضرت حسن بن علیؓ نے فرمایا یہ جان لو کہ حلم اور بردباری زینت ہے اور وعدہ پورا کرنا مردانگی ہے اور جلد بازی بے وقوفی ہے اور سفر کرنے سے انسان کمزور ہو جاتا ہے اور کمینے لوگوں کے ساتھ بیٹھنا عیب کا کام ہے اور فاسق فاجر لوگوں کے ساتھ میل جول رکھنے سے انسان پر تہمت لگتی ہے۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.8 Pg.237)."]]},{"b":[["n",[["حضرت حسن بن علیؓ نے فرمایا لوگ چار قسم کے ہوتے ہیں۔ ایک تو وہ جسے بھلائی میں سے بہت حصہ ملا لیکن اس کے اخلاق اچھے نہیں۔ دوسرا وہ جس کے اخلاق تو اچھے ہیں لیکن بھلائی کے کاموں میں اس کا کوئی حصہ نہیں۔ تیسرا وہ جس کے نہ اخلاق اچھے ہیں اور نہ بھلائی کے کاموں میں اس کا کوئی حصہ ہے، یہ تمام لوگوں میں سب سے برا ہے۔ چوتھا وہ جس کے اخلاق بھی اچھے ہیں اور بھلائی کے کاموں میں اس کا حصہ بھی خوب ہے، یہ لوگوں میں سب سے افضل ہے۔",""],[" (3)","s"]]]],"f":[["(3)","Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.8 Pg.237)."]]}]},"216":{"lead":[],"stories":[{"b":[["n",[["حضرت زیاد بن ماہکؒ","b"],[" کہتے ہیں حضرت شداد بن اوسؓ فرمایا کرتے تھے آپ لوگوں نے خیر نہیں دیکھی، اس کے اسباب دیکھے ہیں اور شر نہیں دیکھا، اس کے اسباب دیکھے ہیں۔ ساری کی ساری خیر اپنی تمام صورتوں کے ساتھ جنت میں ہے اور سارا کا سارا شر اپنی تمام صورتوں کے ساتھ جہنم کی آگ میں ہے اور دنیا تو وہ سامان ہے جو سامنے موجود ہے، نظر آ رہا ہے، جس میں سے نیک اور برے سب کھا رہے ہیں اور آخرت ایک سچا وعدہ ہے جس میں سب پر غالب آنے والے بادشاہ یعنی ",""],["ٱللَّٰه","a"],[" تعالیٰ فیصلہ کریں گے۔ اور دنیا اور آخرت میں سے ہر ایک کے بیٹے یعنی ہر ایک کے چاہنے والے ہیں، لہٰذا تم آخرت کے بیٹوں میں سے بنو اور دنیا کے بیٹوں میں سے نہ بنو۔",""]]]],"f":[]},{"b":[["n",[["حضرت ابوالدرداءؓ نے فرمایا بعض لوگوں کو علم تو مل جاتا ہے لیکن بردباری نہیں ملتی اور حضرت ابویعلیؓ (یہ حضرت شدادؓ کی کنیت ہے) کو علم بھی ملا اور بردباری بھی۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Nu'aym in his Hilyah (Vol.1 Pg.264)."]]}]},"217":{"lead":[],"stories":[{"b":[["n",[["حضرت جندب بجلیؓ نے فرمایا ",""],["ٱللَّٰه","a"],[" سے ڈرو اور قرآن پڑھو کیونکہ قرآن اندھیری رات کا نور ہے اور چاہے دن میں مشقت اور فاقہ ہو لیکن قرآن پڑھنے سے دن میں رونق آ جاتی ہے۔ اور جب کوئی مصیبت تمہارے مال اور تمہارے جسم میں سے کسی ایک پر آنے لگے تو کوشش کرو کہ مال کا نقصان ہو جائے اور جان کا نہ ہو، اور جب مصیبت تمہاری جان اور تمہارے دین میں سے کسی ایک پر آنے لگے تو کوشش کرو کہ جان کا نقصان ہو جائے لیکن دین کا نہ ہو۔ اور اصل ناکام اور نامراد وہ ہے جو اپنے دین میں ناکام و نامراد ہو اور حقیقت میں ہلاک ہونے والا وہ ہے جس کا دین برباد ہو جائے۔ غور سے سنو! جنت میں جانے کے بعد کوئی فقر و فاقہ نہیں ہوگا اور جہنم میں جانے کے بعد غنا اور مالداری کی کوئی صورت باقی نہیں رہے گی کیونکہ جہنم کا قیدی کبھی چھوٹ نہیں سکے گا اور اس کا زخمی کبھی ٹھیک نہیں ہوگا اور نہ اس کی آگ کبھی بجھے گی۔ اور اگر کسی مسلمان نے کسی مسلمان کا مٹھی بھر خون بہایا ہوگا تو یہ اس کے لیے جنت میں جانے سے رکاوٹ بن جائے گا اور جب بھی جنت کے کسی دروازے سے داخل ہونا چاہے گا تو وہاں اسے یہ خون دھکے دیتا ہوا ملے گا۔ اور جان لو کہ آدمی جب مرنے کے بعد دفن کر دیا جاتا ہے تو سب سے پہلے اس کا پیٹ سڑتا ہے اور اس میں سے بدبو آنے لگتی ہے، لہٰذا اس بدبو کے ساتھ حرام روزی سے گندگی کا اضافہ نہ کرو اور اپنے مسلمان بھائیوں کے مال کے بارے میں ",""],["ٱللَّٰه","a"],[" سے ڈرو اور خون بہانے سے بچو۔",""],[" (1)","s"]]]],"f":[["(1)","Bayhaqi, as quoted in Kanzul Ummaal (Vol.8 Pg.222)."]]}]},"218":{"lead":[],"stories":[{"b":[["n",[["حضرت عامر بن سلیمؒ","b"],[" کہتے ہیں ہم ایک جنازے کے ساتھ باب دمشق میں گئے۔ ہمارے ساتھ حضرت ابوامامہ باہلیؓ بھی تھے۔ جب وہ نماز جنازہ پڑھا چکے اور لوگ جنازے کو دفن کرنے لگے تو انہوں نے فرمایا اے لوگو! تم اب تو صبح و شام ایسی جگہ گزار رہے ہو جہاں تم لوگ اپنے حصہ کی نیکیاں اور برائیاں جمع کر رہے ہو۔ پھر حضرت ابوامامہؓ نے قبر کی طرف اشارہ کرتے ہوئے فرمایا عنقریب یہاں سے کوچ کر کے اس (قبر والی) جگہ آ جاؤ گے۔ یہ قبر تنہائی کا گھر ہے، اندھیرے کا گھر ہے، کیڑوں کا گھر ہے اور تنگی کا گھر ہے، لیکن جس کے لیے ",""],["ٱللَّٰه","a"],[" قبر کو کشادہ کر دیں تو یہ الگ بات ہے۔ پھر قیامت کے دن تم لوگ یہاں سے منتقل ہو کر میدان حشر میں پہنچ جاؤ گے اور وہاں ",""],["ٱللَّٰه","a"],[" کا ایک حکم آئے گا جس سے بہت سے چہرے سفید اور بہت سے سیاہ ہو جائیں گے۔ پھر وہاں سے دوسری جگہ چلے جاؤ گے۔ اس جگہ سب لوگوں پر سخت اندھیرا چھا جائے گا، پھر نور تقسیم کیا جائے گا۔ مومن لوگوں کو تو نور مل جائے گا لیکن کافروں اور منافقوں کو ایسے ہی چھوڑ دیا جائے گا، انہیں کچھ بھی نور نہیں ملے گا۔ اور ",""],["ٱللَّٰه","a"],[" تعالیٰ نے اپنی کتاب میں اس مثال کو ان الفاظ میں بیان کیا ہے",""]]],["q",[["أَوْ كَظُلُمَاتٍ فِي بَحْرٍ لُّجِّيٍّ يَغْشَاهُ مَوْجٌ مِّن فَوْقِهِ مَوْجٌ مِّن فَوْقِهِ سَحَابٌ ۚ ظُلُمَاتٌ بَعْضُهَا فَوْقَ بَعْضٍ إِذَا أَخْرَجَ يَدَهُ لَمْ يَكَدْ يَرَاهَا ۗ وَمَن لَّمْ يَجْعَلِ ٱللَّهُ لَهُ نُورًا فَمَا لَهُ مِن نُّورٍ","a"]]],["p",[["ترجمہ: \"یا وہ ایسے ہیں جیسے بڑے گہرے سمندر کے اندرونی اندھیرے کہ اس کو ایک بڑی لہر نے ڈھانک لیا ہو، اس (لہر) کے اوپر دوسری لہر، اس کے اوپر بادل (ہے، غرض) اوپر تلے بہت سے اندھیرے (ہی اندھیرے) ہیں کہ اگر (کوئی ایسی حالت میں) اپنا ہاتھ نکالے (اور دیکھنا چاہے) تو دیکھنے کا احتمال بھی نہیں اور جس کو ",""],["ٱللَّٰه","a"],[" ہی نور (ہدایت) نہ دے اس کو (کہیں سے بھی) نور نہیں میسر ہو سکتا۔\" (سورۂ نور، آیت 40)۔ اور کافر و منافق مومن کے نور سے روشنی حاصل نہیں کر سکیں گے، جیسے اندھا بینا کی دیکھنے کی طاقت سے کوئی فائدہ حاصل نہیں کر سکتا۔ منافق مرد اور منافق عورتیں ایمان والوں سے (پل صراط پر) کہیں گے",""]]],["q",[["ٱنظُرُونَا نَقْتَبِسْ مِن نُّورِكُمْ قِيلَ ٱرْجِعُوا۟ وَرَآءَكُمْ فَٱلْتَمِسُوا۟ نُورًا","a"]]],["p",[["ترجمہ: \"(ذرا) ہمارا انتظار کر لو ہم بھی تمہارے نور سے کچھ روشنی حاصل کر لیں۔ ان کو جواب دیا جائے گا کہ تم اپنے پیچھے لوٹ جاؤ پھر (وہاں سے) روشنی تلاش کرو۔\" (سورۂ حدید، آیت 13)۔ اس طرح ",""],["ٱللَّٰه","a"],[" تعالیٰ منافقوں کو ان کی چالبازی کی سزا دیں گے جیسے کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے فرمایا ہے",""]]],["q",[["يُخَادِعُونَ ٱللَّهَ وَهُوَ خَادِعُهُمْ","a"]]],["p",[["ترجمہ: \"چالبازی کرتے ہیں ",""],["ٱللَّٰه","a"],[" سے حالانکہ ",""],["ٱللَّٰه","a"],[" اس چال کی سزا ان کو دینے والے ہیں۔\" (سورۂ نساء، آیت 142)۔ پھر کفار اور منافقین اسی جگہ واپس آئیں گے جہاں نور تقسیم ہوا تھا لیکن انہیں وہاں کچھ نہیں ملے گا، پھر وہ دوبارہ مسلمانوں کے پاس آئیں گے، پھر ان کے اور مسلمانوں کے درمیان ایک دیوار قائم کر دی جائے گی جس میں ایک دروازہ (بھی) ہوگا۔",""]]],["q",[["بَاطِنُهُۥ فِيهِ ٱلرَّحْمَةُ وَظَـٰهِرُهُۥ مِن قِبَلِهِ ٱلْعَذَابُ","a"]]],["p",[["ترجمہ: \"(جس کی کیفیت یہ ہے کہ) اس کے اندرونی جانب میں رحمت ہوگی اور بیرونی جانب میں عذاب ہوگا۔\" (سورۂ حدید، آیت 13)۔ حضرت سلیم بن عامرؒ کہتے ہیں یوں منافق دھوکے میں پڑے رہیں گے یہاں تک کہ نور تقسیم ہو جائے گا اور ",""],["ٱللَّٰه","a"],[" تعالیٰ منافق اور مومنوں کو الگ کر دیں گے۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Abi Haatim, as quoted in the Tafseer of Ibn Katheer (Vol.4 Pg.308). Bayhaqi has reported a similar narration in his Asmaa was Sifaat (Pg.340) from Sulaym bin Aamir."]]},{"b":[["n",[["حضرت سلیمان بن حبیبؒ","b"],[" کہتے ہیں میں ایک جماعت کے ساتھ حضرت ابوامامہؓ کی خدمت میں حاضر ہوا تو میں نے دیکھا کہ وہ تو بڑے میاں ہیں اور ان کا ظاہری منظر جو نظر آ رہا تھا ان کی عقل اور ان کی گفتگو اس سے کہیں زیادہ اچھی تھی۔ انہوں نے سب سے پہلے ہم سے یہ بات کہی کہ اس مجلس میں بیٹھنے کی وجہ سے ",""],["ٱللَّٰه","a"],[" تعالیٰ اپنے احکام تم تک پہنچا رہے ہیں اور یہ مجلس تم پر ",""],["ٱللَّٰه","a"],[" کی حجت ہے کیونکہ حضورؐ کو جو کچھ دے کر بھیجا گیا تھا آپ نے وہ سب کچھ اپنے صحابہؓ کو پہنچا دیا تھا اور آپ کے صحابہؓ نے جو کچھ حضورؐ سے سنا تھا وہ سب آگے پہنچا دیا۔ لہٰذا تم جو کچھ سن رہے ہو اسے آگے پہنچا دینا۔ تین آدمی ایسے ہیں جو ",""],["ٱللَّٰه","a"],[" کی ذمہ داری میں ہیں یہاں تک کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ یا تو انہیں جنت میں داخل کریں گے یا اجر و ثواب اور غنیمت دے کر انہیں واپس کریں گے۔ ایک تو وہ آدمی جو ",""],["ٱللَّٰه","a"],[" کے راستے میں نکلا، یہ بھی ",""],["ٱللَّٰه","a"],[" کی ذمہ داری میں ہے یہاں تک کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ اسے (شہادت کا مرتبہ دے کر) جنت میں داخل کریں گے یا اجر و ثواب اور مال غنیمت دے کر واپس کریں گے۔ دوسرا وہ آدمی جس نے وضو کیا پھر مسجد گیا، وہ بھی ",""],["ٱللَّٰه","a"],[" کی ذمہ داری میں ہے یہاں تک کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ یا تو اسے (موت دے کر) جنت میں داخل کریں گے یا اجر و ثواب اور مال غنیمت دے کر واپس کریں گے۔ تیسرا وہ آدمی جو اپنے گھر میں سلام کر کے داخل ہو۔ پھر فرمایا جہنم پر ایک بڑا پل ہے جس سے پہلے سات چھوٹے پل ہیں۔ ان میں سے درمیان والے پل پر حقوق العباد کا فیصلہ ہوگا۔ چنانچہ ایک بندے کو لایا جائے گا، جب وہ درمیان والے پل پر پہنچ جائے گا تو اس سے پوچھا جائے گا تم پر قرضہ کتنا تھا؟ وہ اپنے قرضہ کا حساب لگانے لگے گا۔ پھر حضرت ابوامامہؓ نے یہ آیت پڑھی",""]]],["q",[["وَلَا يَكْتُمُونَ ٱللَّهَ حَدِيثًا","a"]]],["p",[["ترجمہ: \"اور ",""],["ٱللَّٰه","a"],[" تعالیٰ سے کسی بات کا اخفا نہ کر سکیں گے۔\" (سورۂ نساء، آیت 42)۔ پھر وہ بندہ کہے گا اے میرے رب! مجھ پر اتنا قرضہ تھا۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ فرمائیں گے اپنا قرضہ ادا کر۔ وہ کہے گا میرے پاس تو کوئی چیز نہیں ہے اور مجھے معلوم بھی نہیں کہ میں کس چیز سے قرضہ اتار سکتا ہوں۔ پھر فرشتوں سے کہا جائے گا اس کی نیکیاں لے لو (اور اس کے قرض خواہوں کو دے دو)۔ چنانچہ اس کی نیکیاں لے کر قرض خواہوں کو دی جاتی رہیں گی یہاں تک کہ اس کے پاس ایک بھی نیکی باقی نہیں رہے گی۔ جب اس کی تمام نیکیاں ختم ہو جائیں گی تو کہا جائے گا اس سے مطالبہ کرنے والوں کے گناہ لے کر اس پر ڈال دو۔ چنانچہ مجھے یہ بات پہنچی ہے کہ بہت سے لوگ پہاڑوں کے برابر نیکیاں لے کر آئیں گے اور اپنے حقوق کا ان سے مطالبہ کرنے والوں کو ان سے نیکیاں لے کر دی جاتی رہیں گی یہاں تک کہ ان کی ایک بھی نیکی باقی نہیں رہے گی، پھر مطالبہ کرنے والوں کے گناہ ان پر ڈالے جائیں گے یہاں تک کہ وہ گناہ پہاڑوں کے برابر ہو جائیں گے۔ پھر حضرت ابوامامہؓ نے فرمایا جھوٹ سے بچو کیونکہ جھوٹ فسق و فجور کی رہبری کرتا ہے اور فسق و فجور جہنم کا راستہ دکھاتے ہیں اور سچ بولنے کو لازم پکڑو کیونکہ سچ نیکی کا راستہ دکھاتا ہے اور نیکی جنت کا راستہ دکھاتی ہے۔ پھر فرمایا اے لوگو! تم تو زمانہ جاہلیت والوں سے زیادہ گمراہ ہو۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے تمہیں درہم و دینار اس لیے دیے ہیں کہ تم ایک درہم اور ایک دینار ",""],["ٱللَّٰه","a"],[" کے راستے میں خرچ کر کے سات سو درہم اور سات سو دینار کا ثواب حاصل کرو اور پھر تم لوگ تھیلیوں میں درہم و دینار بند کر کے رکھتے ہو اور ",""],["ٱللَّٰه","a"],[" کے راستہ میں خرچ نہیں کرتے ہو۔ غور سے سنو! ",""],["ٱللَّٰه","a"],[" کی قسم! یہ تمام فتوحات ایسی تلواروں کے ذریعہ سے ہوئی ہیں جن میں زینت کے لیے سونا اور چاندی لگا ہوا نہیں تھا بلکہ کچا پٹھا، سیسہ اور لوہا لگا ہوا تھا۔",""]]]],"f":[]}]},"219":{"lead":[],"stories":[{"b":[["n",[["حضرت عبد",""],["ٱللَّٰه","a"],[" بن بسرؓ نے فرمایا متقی لوگ سردار ہیں اور علماء قائد اور رہنما ہیں۔ ان کے ساتھ بیٹھنا عبادت ہے بلکہ عبادت سے بڑھ کر ہے اور دن و رات کے گزرنے کی وجہ سے تمہاری عمریں کم ہوتی جا رہی ہیں لیکن تمہارے اعمال کو بڑی حفاظت سے رکھا جا رہا ہے، لہٰذا تم زاد سفر تیار کر لو اور یوں سمجھو کہ تم لوٹنے کی جگہ یعنی آخرت میں پہنچ گئے ہو۔",""],[" (1)","s"]]]],"f":[["(1)","Bayhaqi and Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.8 Pg.224)."]]}]}}});
